The 99 Names of Allah
- #0 Best of Names 7:180; 20:8; 59:24
- #1 Ar-Rahman     அளவற்ற அருளாளன் (The Beneficent)  1:3; 17:110
- #2 Ar-Raheem      நிகரற்ற அன்புடையோன் (The Merciful)  2:163; 3:31; 4:100; 5:3
- #3 Al-Malik       பேரரசன் (The King/Lord)  20:114; 23:116; 59:23
- #4 Al-Quddus      மகா தூயவன், பரிசுத்தமானவன் (The Most Sacred)  59:23; 62:1
- #5 As-Salaam      சாந்தி அளிப்பவன் (The Giver of Peace)  59:23
- #6 Al-Mu'min      அபயமளிப்பவன் (The Granter of Security)  59:23
- #7 Al-Muhaymin    பாதுகாப்பவன் (Guardian Over All)  59:23
- #8 Al-Aziz        அனைத்தையும் மிகைத்தவன் (The Mighty One)  3:6; 4:158; 9:40; 48:7
- #9 Al-Jabbar      சர்வ வல்லமை படைத்தவன் (The Omnipotent)  59:23
- #10 Al-Mutakabbir பெருமைக்குரியவன் (The Possessor of Greatness)  59:23
- #11 Al-Khaliq     படைப்பாளன், படைப்பவன் (The Creator)  6:102; 13:16; 39:62; 40:62; 59:24
- #12 Al-Bari'      உருவாக்குபவன் (The Initiator/Evolver)  59:24
- #13 Al-Musawwir   உருவம் அமைப்பவன் (The Flawless Shaper)  59:24
- #14 Al-Ghaffar    மிகவும் மன்னிக்கக்கூடியவன் (The Great Forgiver)  20:82; 38:66; 39:5; 40:42; 71:10
- #15 Al-Qahhar     அடக்கி ஆளுபவன் (The Subduer/Overcomer)  13:16; 14:48; 38:65; 39:4; 40:16
- #16 Al-Wahhab     வாரி வழங்குபவன் (The Supreme Bestower)  3:8; 38:9; 38:35
