Matching Ayahs
- = அலிஃப், லாம், மீம். 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = அவர்கள் தங்கள் இறைவனிடமிருந்து நேர்வழி பெற்றவர்கள்; அவர்களே வெற்றி பெற்றவர்கள். 2:5; 31:5
- = இஸ்ரவேல் சந்ததியினரே! நான் உங்களுக்கு அளித்த என் அருட்கொடையை நினைவு கூருங்கள்; மேலும், நான் உங்களை உலக மக்கள் (அனைவர்) மீதும் மேன்மையாக்கினேன். 2:47; 2:122
- = அந்த சமூகம் (காலத்தால்) கடந்து போய்விட்டது. அவர்கள் சம்பாதித்தது அவர்களுக்கு; நீங்கள் சம்பாதித்தது உங்களுக்கு. அவர்கள் செய்து கொண்டிருந்ததைப் பற்றி நீங்கள் கேட்கப்பட மாட்டீர்கள். 2:134; 2:141
- = அவர்கள் அதில் என்றென்றும் தங்குவார்கள். அவர்களின் வேதனை தணிக்கப்பட மாட்டாது; மேலும், அவர்களுக்கு அவகாசமும் வழங்கப்படாது. 2:162; 3:88
- = ஆனால், இதற்குப் பின் தவ்பா (மனந்திரும்பி) செய்து, தங்களைச் சீர்படுத்திக் கொள்பவர்கள் தவிர. நிச்சயமாக அல்லாஹ் மன்னிப்பவன், மிக்க கருணையுடையவன். 3:89; 24:5
- = எவர்கள் நிராகரித்து, நம்முடைய வசனங்களைப் பொய்யாக்குகிறார்களோ – அவர்கள் நரகவாசிகள். 5:10; 5:86
- = அவர்களுடைய இறைவனின் அத்தாட்சிகளிலிருந்து ஓர் அத்தாட்சி அவர்களிடம் வந்தால், அவர்கள் அதிலிருந்து புறமுதுகிட்டு விலகுகிறார்கள். 6:4; 36:46
- = உங்களுக்கு முன்னும் தூதர்கள் ஏளனம் செய்யப்பட்டனர்; ஆனால், ஏளனம் செய்து கொண்டிருந்தவர்களை, அவர்கள் ஏளனம் செய்து கொண்டிருந்த (வேதனை) சூழ்ந்து கொண்டது. 6:10; 21:41
- = கூறுவீராக: "நான் என் இறைவனுக்கு மாறு செய்தால், மகத்தான நாளின் வேதனைக்கு நான் பயப்படுகிறேன்." 6:15; 39:13
- = ஆக, பூகம்பம் அவர்களைப் பற்றிக் கொண்டது; அவர்கள் தங்கள் வீடுகளில் முகங்குப்புற விழுந்து (இறந்து) கிடந்தனர். 7:78; 7:91
- = பின்னர், அவர் (மூசா) தம் கோலை எறிந்தார்; உடனே, அது ஒரு பிரத்தியட்சமான பெரும் பாம்பாக ஆயிற்று. 7:107; 26:32
- = மேலும், அவர் தம் கையை (வெளியே) எடுத்தார்; உடனே, அது பார்ப்பவர்களுக்கு வெண்மையாக (ஒளிர்ந்தது). 7:108; 26:33
- = அவர்கள் கூறினார்கள்: "நாங்கள் அகிலங்களின் இறைவனை நம்பினோம்." 7:121; 26:47
- = மூசா மற்றும் ஹாரூன் ஆகியோரின் இறைவன். 7:122; 26:48
- = நான் அவர்களுக்கு அவகாசம் தருவேன். நிச்சயமாக, என் சூழ்ச்சி உறுதியானது. 7:183; 68:45
- = அவன்தான் தன் தூதரை நேர்வழியும் உண்மை மார்க்கமுமாக அனுப்பினான் – அதை, முஷ்ரிக்குகள் வெறுத்தாலும், சகல மார்க்கங்களையும் விட உயர்த்துவதற்காக. 9:33; 61:9
- = நபியே! நிராகரிப்பவர்களுடனும், நயவஞ்சகர்களுடனும் போர் புரிவீராக; மேலும், அவர்களிடம் கடுமையாக நடந்து கொள்வீராக. அவர்களின் தங்குமிடம் நரகமாகும்; அது மிகக் கெட்ட சேருமிடம்! 9:73; 66:9
- = மேலும், அவர்கள் கூறுகிறார்கள்: "நீங்கள் உண்மையாளர்களாக இருந்தால், இந்த வாக்குறுதி எப்போது (நிறைவேறும்)?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = நாம் மூசாவை நமது அத்தாட்சிகளுடனும், தெளிவான அதிகாரத்துடனும் அனுப்பினோம். 11:96; 40:23
- = நாம் மூசாவுக்கு வேதத்தைக் கொடுத்தோம்; ஆனால், அதில் கருத்து வேறுபாடு ஏற்பட்டது. உமது இறைவனிடமிருந்து முன்னதாக ஒரு வாக்கு இல்லாவிட்டால், அவர்களுக்கிடையே (இப்போதே) தீர்ப்பு வழங்கப்பட்டிருக்கும். மேலும், நிச்சயமாக அவர்கள் அதைப் பற்றிய ஐயப்பாட்டில் உள்ளனர். 11:110; 41:45
- = அது அல்லாஹ்வுக்கு கடினமானதல்ல. 14:20; 35:17
- = "நான் அவனை (ஆதமை) உருவாக்கி, என் ஆன்மாவிலிருந்து அவனில் ஊதும் போது, நீங்கள் அவனுக்கு சுஜூது செய்து விழுங்கள்." 15:29; 38:72
- = ஆக, மலக்குகள் அனைவரும் ஒன்றாக சுஜூது செய்தனர். 15:30; 38:73
- = (அல்லாஹ்) கூறினான்: "அவ்வாறாயின், இதிலிருந்து வெளியேறு; நிச்சயமாக நீ விரட்டப்பட்டவன்." 15:34; 38:77
- = (இப்லீஸ்) கூறினான்: "என் இறைவனே! அவ்வாறாயின், அவர்கள் (மீண்டும்) எழுப்பப்படும் நாள் வரை எனக்கு அவகாசம் அளிப்பாயாக." 15:36; 38:79
- = (அல்லாஹ்) கூறினான்: "அவ்வாறாயின், நிச்சயமாக நீ அவகாசம் அளிக்கப்பட்டவர்களில் ஒருவன்." 15:37; 38:80
- = நிர்ணயிக்கப்பட்ட காலத்தின் நாள் வரை." 15:38; 38:81
- = அவர்களில் உனது தூய்மையான அடியார்களைத் தவிர. 15:40; 38:83
- = நிச்சயமாக, இறையச்சமுள்ளவர்கள் சுவனபூங்காக்களிலும், நீரூற்றுகளிலும் இருப்பார்கள். 15:45; 51:15
- = அவர் (இப்ராஹீம்) கேட்டார்: "அவ்வாறாயின், தூதர்களே! உங்களுடைய பணி என்ன?" 15:57; 51:31
- = அவர்கள் கூறினார்கள்: "நாங்கள் குற்றவாளிகளான ஒரு சமூகத்தின் பால் அனுப்பப்பட்டுள்ளோம்." 15:58; 51:32
- = எவர்கள் ஈமான் கொண்டு, தங்கள் ஈமானை அநீதியுடன் கலக்கவில்லையோ – அவர்களுக்குப் பாதுகாப்பு உண்டு; மேலும், அவர்கள் நேர்வழி பெற்றவர்கள். 16:42; 29:59
- = அவர்கள் நாம் அவர்களுக்கு அளித்ததை மறுப்பதற்காக (இதைச் செய்கிறோம்). ஆதலால், நீங்கள் சுகம் அனுபவியுங்கள்; பின்னர், (அதன் விளைவை) அறிந்து கொள்வீர்கள். 16:55; 30:34
- = பின்னர், அவர் (துல்கர்னைன்) ஒரு வழியைப் பின்பற்றினார். 18:89; 18:92
- = ஃபிர்அவ்னிடம் செல்லுங்கள்; நிச்சயமாக அவன் வரம்பு மீறியுள்ளான். 20:24; 79:17
- = மேலும், அவர்கள் தங்கள் கற்பைப் பாதுகாப்பவர்கள். 23:5; 70:29
- = தங்கள் மனைவியர் அல்லது தங்கள் வலது கைகள் சொந்தமாக்கியவர்கள் தவிர – நிச்சயமாக அவர்கள் பழிக்கத்தக்கவர்கள் அல்லர். 23:6; 70:30
- = ஆனால், இதற்கு அப்பால் எவர் தேடுகிறாரோ – அவர்கள் வரம்பு மீறுபவர்கள். 23:7; 70:31
- = மேலும், அவர்கள் தங்கள் பொறுப்புகளையும், உடன்படிக்கைகளையும் பேணுபவர்கள். 23:8; 70:32
- = (நூஹ்) கூறினார்: "என் இறைவனே! அவர்கள் என்னைப் பொய்யாக்கியதால், எனக்கு உதவி செய்வாயாக." 23:26; 23:39
- = தா, ஸீன், மீம். 26:1; 28:1
- = இவை தெளிவான வேதத்தின் வசனங்களாகும். 26:2; 28:2
- = நிச்சயமாக இதில் ஓர் அத்தாட்சி உள்ளது; ஆனால், அவர்களில் பெரும்பாலோர் ஈமான் கொண்டவர்களாக இல்லை. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = மேலும், நிச்சயமாக உமது இறைவன் – அவனே மிகைத்தவன், மிக்க கருணையுடையவன். 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = மேலும், மற்றவர்களை நாம் மூழ்கடித்தோம். 26:66; 37:82
- = நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய தூதனாவேன். 26:107; 26:125; 26:143; 26:162; 26:178
- = ஆகவே, நீங்கள் அல்லாஹ்வுக்கு அஞ்சுங்கள்; மேலும், எனக்கு கீழ்படியுங்கள். 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = இதற்காக நான் உங்களிடம் எந்தக் கூலியும் கேட்கவில்லை. என் கூலி, அகிலங்களின் இறைவனிடமே தவிர வேறில்லை. 26:109; 26:127; 26:145; 26:164; 26:180
- = சுவனபூங்காக்களிலும், நீரூற்றுகளிலும். 26:147; 44:52
- = அவர்கள் கூறினார்கள்: "நீ மந்திரிக்கப்பட்டவர்களில் ஒருவன்." 26:153; 26:185
- = ஆனால், அவருடைய மனைவியைத் தவிர – அவள் பின்னால் தங்கி விடுபவர்களில் ஒருத்தியாவாள் என்று நாம் நிர்ணயித்தோம். 26:171; 37:135
- = பின்னர், மற்றவர்களை நாம் அழித்தோம். 26:172; 37:136
- = மேலும், அவர்கள் மீது (கற்களின்) மழையைப் பொழிந்தோம்; மேலும், அச்சுறுத்தப்பட்டவர்களின் மழை மிகக் கெட்டதாய் அமைந்தது! 26:173; 27:58
- = அப்படியிருக்க, அவர்கள் நம் வேதனையை அவசரப்படுத்துகிறார்களா? 26:204; 37:176
- = எவர்கள் தொழுகையை நிலைநாட்டுகிறார்களோ, ஸகாத் கொடுக்கிறார்களோ, மேலும், அவர்கள் மறுமையில் உறுதியான நம்பிக்கை உடையவர்களோ. 27:3; 31:4
- = மேலும், (நபியே!) அந்நாளில் அவன் அவர்களை அழைத்து, "நீங்கள் (எனக்கு) இணையாகக் கருதிய எனது 'இணைகள்' எங்கே?" என்று கேட்பான். 28:62; 28:74
- = மேலும், எங்கள் மூதாதையர்களோ? 37:17; 56:48
- = மேலும், அவர்கள் ஒருவரையொருவர் நெருங்கி, கேள்வி கேட்டுக் கொள்வார்கள். 37:27; 52:25
- = ஆனால், (அவர்கள்) அல்லாஹ்வின் தூய்மையான அடியார்கள். 37:40; 37:74; 37:128; 37:160
- = சுகங்கள் நிறைந்த சுவனபூங்காக்களில். 37:43; 56:12
- = மேலும், பிற்காலத்தவர்களிடையே அவருக்கு (ஸுலைமானுக்கு) நன்மதிப்பை நாம் நிலைநிறுத்தினோம்: 37:78; 37:108; 37:129
- = நிச்சயமாக, நாம் நன்மை செய்வோருக்கு இவ்வாறே கூலி வழங்குகிறோம். 37:80; 37:121; 37:131; 77:44
- = நிச்சயமாக, அவர் நம் ஈமானுள்ள அடியார்களில் ஒருவராக இருந்தார். 37:81; 37:111; 37:132
- = உங்களுக்கு என்ன ஆயிற்று? எவ்வாறு தீர்ப்பு வழங்குகிறீர்கள்? 37:154; 68:36
- = இது (குர்ஆன்) அகிலங்களுக்கு ஒரு நினைவூட்டல் அல்லாது வேறில்லை. 38:87; 81:27
- = வேதத்தின் அருளுதல் அல்லாஹ்விடமிருந்து – மிகைத்தவனும், ஞானமுடையவனுமான (அவனிடமிருந்து) ஆகும். 39:1; 45:2; 46:2
- = ஹா, மீம். 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = தெளிவான வேதத்தின் மீது சத்தியமாக. 43:2; 44:2
- = ஆகவே, அவர்கள் தங்களுக்கு வாக்களிக்கப்பட்ட தங்கள் அந்த நாளைச் சந்திக்கும் வரை, வீண் பேச்சிலும் விளையாட்டிலும் மூழ்கிக் கிடக்க அவர்களை விட்டுவிடுவீராக. 43:83; 70:42
- = (அவர்களுக்குக் கூறப்படும்): "நீங்கள் செய்து கொண்டிருந்ததன் பயனாக, திருப்தியுடன் உண்ணுங்கள்; பருகுங்கள்." 52:19; 77:43
- = அல்லது, நீர் அவர்களிடம் கூலி கேட்கிறீரோ? அதனால், அவர்கள் கடனில் மூழ்கி விட்டனரோ? 52:40; 68:46
- = அல்லது, அவர்களிடம் மறைவான அறிவு உள்ளதோ? அதனால், அவர்கள் (அதை) எழுதுகிறார்களோ? 52:41; 68:47
- = என் வேதனையும், என் எச்சரிக்கைகளும் எப்படி (கொடியனவாக) இருந்தன! 54:16; 54:21; 54:30
- = நாம் குர்ஆனை நினைவு கூறுவதற்காக இலகுவாக்கினோம். ஆகவே, (இதை) நினைவு கூறுவோர் உண்டோ? 54:17; 54:22; 54:32; 54:40
- = ஆகவே, உங்கள் இறைவனின் அருட்கொடைகளில் எதை நீங்கள் நிராகரிப்பீர்கள்? 55:13; 55:16; 55:18; 55:21; 55:23; 55:25; 55:28; 55:30; 55:32; 55:34; 55:36; 55:38; 55:40; 55:42; 55:45; 55:47; 55:49; 55:51; 55:53; 55:55; 55:57; 55:59; 55:61; 55:63; 55:65; 55:67; 55:69; 55:71; 55:73; 55:75; 55:77
- = முன்னோர்களில் ஒரு பெரும் கூட்டத்தினர். 56:13; 56:39
- = மாறாக, நாங்கள் (விளைச்சலில்) இழப்பு அடைந்து விட்டோமோ? 56:67; 68:27
- = ஆகவே, உமது மகத்தான இறைவனின் பெயரைத் துதிப்பீராக. 56:74; 56:96; 69:52
- = இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்டதாகும். 56:80; 69:43
- = வானங்களிலும், பூமியிலும் உள்ள அனைத்தும் அல்லாஹ்வைத் துதிக்கின்றன; மேலும், அவன் மிகைத்தவன், ஞானமுடையவன். 59:1; 61:1
- = நம் வசனங்கள் அவனுக்கு ஓதப்படும் போது, அவன் கூறுகிறான்: "இவை முன்னோர்களின் கதைகள்!" 68:15; 83:13
- = ஆக, அவன் திருப்திகரமான வாழ்வில் இருப்பான். 69:21; 101:7
- = உயர்ந்த சுவனபூங்காவில். 69:22; 88:10
- = மேலும், அவன் ஏழைகளுக்கு உணவளிக்கத் தூண்டுவதில்லை. 69:34; 107:3
- = நிச்சயமாக இது (குர்ஆன்) கண்ணியமிக்க தூதரின் (ஜிப்ரீலின்) சொல்லாகும். 69:40; 81:19
- = நிச்சயமாக இது ஓர் அறிவுரையாகும்; ஆதலால், விரும்பியவர் தம் இறைவனிடம் செல்லும் வழியைப் பிடித்துக் கொள்ளட்டும். 73:19; 76:29
- = ஆதலால், விரும்பியவர் அதை நினைவு கூரட்டும். 74:55; 80:12
- = அந்நாளில் (வேதத்தை) பொய்யாக்கினவர்களுக்குக் கேடு! 77:15; 77:19; 77:24; 77:28; 77:34; 77:37; 77:40; 77:45; 77:47; 77:49; 83:10
- = நிச்சயமாக, நல்லோர் இன்பத்தில் இருப்பர். 82:13; 83:22
- = அது (நல்லோரின் பதிவேடு) எழுதப்பட்ட பதிவாகும். 83:9; 83:20
- = (உயர்ந்த) ஆசனங்களில் (அமர்ந்து) பார்த்துக் கொண்டிருப்பர். 83:23; 83:35
- = மேலும், அது (வானம்) தன் இறைவனுக்குக் கீழ்ப்படிந்தது; மேலும், அது (அவ்வாறு செய்வது) கடமையாகும். 84:2; 84:5
- = மேலும், நீங்கள் வழிபடுவதை நான் வழிபடுபவன் அல்லன். 109:3; 109:5
noblequran.com Schemas
