- உமது இறைவனிடமிருந்து (அனுப்பப்பட்டது) - நீங்கள் ஒரு சமூகத்திற்கு அச்சுறுத்தல் செய்வதற்காக; அவர்களுக்கு உமக்கு முன் எச்சரிக்கை செய்பவர் எவரும் வரவில்லை; அவர்கள்... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- நபியே! நிராகரிப்பவர்களுடனும், நயவஞ்சகர்களுடனும் போராடும்; அவர்களிடம் கடுமையாக நடந்து கொள்ளும். அவர்களின் தங்குமிடம் நரகம் - எத்தனை கெட்ட சேருமிடம்! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- நிச்சயமாக உமது இறைவன், அவர்கள் மாறுபட்டுக் கொண்டிருந்ததைப் பற்றி, உயிர்த்தெழுதல் நாளில் அவர்களுக்கிடையே தீர்ப்பளிப்பான். (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
