- ஆகவே, உமது முகத்தை மஸ்ஜிதுல் ஹராமின் பக்கமாகத் திருப்பும். இன்னும், நீங்கள் எங்கிருந்தாலும், உங்கள் முகங்களை அதன் பக்கமாகத் திருப்புங்கள். (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- இஸ்ரவேலின் மக்களே! நான் உங்களுக்கு அருளிய என் அருட்கொடையையும், நான் உங்களை அகிலங்களின் மீது மேன்மையாக்கினேன் என்பதையும் நினைவு கூருங்கள். (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- ஏழு கொழுத்த பசுக்களை, ஏழு மெலிந்த பசுக்கள் விழுங்குகின்றன; ஏழு பச்சை கதிர்கள், மற்றவை உலர்ந்தவை... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- ஒவ்வொரு சமுதாயத்திற்கும் ஒரு குறிப்பிட்ட தவணை உள்ளது; அவர்களின் தவணை வந்துவிட்டால், ஒரு நொடி கூட தாமதிக்கவும் மாட்டார்கள், முன்னேறவும் மாட்டார்கள். (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
