- எவர் அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் கீழ்ப்படிகிறாரோ, அவரை அவன் சொர்க்கங்களில் பிரவேசிக்கச் செய்வான்; அவற்றின் கீழே ஆறுகள் ஓடும். (وَمَن يُطِعِ اللَّهَ وَرَسُولَهُ يُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 4:13; 48:17
- மெய்யாகவே, அவன் உங்களுக்கு மெல்லியதை, இரத்தத்தை, பன்றியின் இறைச்சியை, மேலும் எவை இன்ன பெயரால் அறுக்கப்பட்டனவோ அவற்றைத் தடுத்துள்ளான். (إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ) 2:173; 16:115
- அல்லாஹ்வையன்றி (வேறு எவரையும்) வணங்காதீர்கள். நிச்சயமாக, நான் உங்களுக்கு ஒரு நாளின் வேதனையைப் பற்றி அஞ்சுகிறேன். (أَن لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ) 11:26; 46:21
- அது மறைவான செய்திகளில் ஒன்றாகும்; அதனை நாங்கள் உமக்கு வஹீ மூலம் அறிவிக்கிறோம்; நீர் அவர்களிடம் இருக்கவில்லை, அப்போது. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- உங்கள் இறைவனிடமிருந்து உங்களில் ஒருவர் மூலம் உங்களுக்கு நினைவூட்டல் வந்ததில் நீங்கள் வியப்படைகிறீர்களா? (அவர்) உங்களை அச்சுறுத்துவதற்காக. (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- கூறுக: "நீங்கள் அல்லாஹ்வையன்றி அழைக்கும் எவற்றையும் நான் வணங்குவதற்குத் தடுக்கப்பட்டுள்ளேன்." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- தங்கள் மனைவியரிடத்திலோ அல்லது அவர்களின் வலக்கை சொந்தமாக்கியவர்களிடத்திலோ (தவிர) – நிச்சயமாக அவர்கள் குற்றம் சாட்டப்பட மாட்டார்கள். (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- ஏனெனில், அல்லாஹ் இரவைப் பகலில் நுழைப்பான்; பகலை இரவில் நுழைப்பான். (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- நெருப்பு, அவர் தம் குடும்பத்தாரிடம் கூறினார்: "தங்குங்கள்; நான் ஒரு நெருப்பைக் கண்டேன்; ஒருவேளை அதிலிருந்து உங்களுக்கு ஏதாவது கொண்டு வருவேன்." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- அவர் கூறினார்: "நான் அவனைவிட மேலானவன்; என்னை நீ நெருப்பிலிருந்து படைத்தாய்; அவனைக் களிமண்ணிலிருந்து படைத்தாய்." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- இன்னும், அவர்களுக்கு "அல்லாஹ் இறக்கியதன் பக்கமும், தூதரின் பக்கமும் வாருங்கள்" என்று கூறப்பட்டால், அவர்கள் சொல்கிறார்கள். (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- அவர்களுக்காக நீர் வருந்தாதீர்; அவர்கள் சூழ்ச்சி செய்வதைப் பற்றி நெருக்கடியிலும் இருக்காதீர். (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- அல்லாஹ் உமக்கு ஒரு தீங்கை நேர்ச்செய்தால், அவனையன்றி அதனை நீக்குபவர் எவருமில்லை; மேலும், அவன். (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- அவர்களுக்கு முன்னிருந்த தலைமுறையினர் அவர்கள் வாழிடங்களில் நடமாடுகிறார்கள். நிச்சயமாக, அதில் அத்தாட்சிகள் உள்ளன. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- இன்னும், அவர்கள் அதனைப் புரிந்து கொள்ளாதபடி அவர்களின் இதயங்களில் திரைகளையும், அவர்களின் காதுகளில் கனத்தையும் நாங்கள் வைத்தோம்; மேலும், அவர்கள். (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- அவர்களின் தூதர்கள் தெளிவான அத்தாட்சிகளுடன் வந்தனர்; எனினும், அல்லாஹ் அவர்களை அநியாயம் செய்யவில்லை; ஆனால், அவர்களே தங்களுக்குத் தாங்களே அநியாயம் செய்து கொண்டார்கள். (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- இன்னும், பூமியில், அல்லாஹ்வையன்றி உங்களுக்கு எந்தப் பாதுகாவலனோ உதவியாளனோ இல்லை. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- பின்னர், நீங்கள் மறைவானவற்றையும், வெளிப்படையானவற்றையும் அறிந்தவனிடம் மீட்டப்படுவீர்கள்; அப்போது, நீங்கள் செய்து கொண்டிருந்தவை குறித்து அவன் உங்களுக்கு அறிவிப்பான். (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- இரவை (அவன் உங்களுக்கு அமைத்தான்) – அதில் நீங்கள் இளைப்பாறுவதற்கு; பகலையும் (உங்களுக்கு அமைத்தான்) பார்வைக்கு வெளிச்சமாக. நிச்சயமாக, அதில் ஒரு சமூகத்திற்கு அத்தாட்சிகள் உள்ளன. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- இன்னும், உமது இறைவனிடமிருந்து உமக்கு இறக்கப்பட்டது அவர்களில் பலருக்கு வழிகேடு மற்றும் நிராகரிப்பையே அதிகமாக்கும். (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- அவர் கூறினார்: "என் சமூகத்தாரே! நான் என் இறைவனின் தெளிவான அத்தாட்சியில் இருந்து, அவன் எனக்கு (வேறு) கொடுத்திருந்தால் நீங்கள் என்ன நினைக்கிறீர்கள்?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- இன்னும், அவர்கள் கூறுகிறார்கள்: "அவருடைய இறைவனிடமிருந்து அவருக்கு ஓர் அத்தாட்சி இறக்கப்படாதது ஏன்?" கூறுக: "நிச்சயமாக." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- அல்லாஹ்விடமிருந்து எந்தத் திருப்பமும் இல்லாத ஒரு நாள் வருவதற்கு முன்னர். (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- அது அல்லாஹ்வின் அருட்கொடையாகும்; அவன் நாடியவர்களுக்கு அதனை வழங்குகிறான்; அல்லாஹ் மகத்தான அருட்கொடை உடையவன். (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- மேலும், நிச்சயமாக, கால்நடைகளில் உங்களுக்கு ஓர் படிப்பினை உள்ளது; அவற்றின் வயிறுகளில் உள்ளவற்றிலிருந்து நாங்கள் உங்களுக்குப் புகட்டுகிறோம். (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- நிச்சயமாக அது அவர்களின் இறைவனிடமிருந்தான உண்மையாகும்; அல்லாஹ் அவர்கள் செய்வதைப் புறக்கணிப்பவனல்ல. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
- அவர்களுக்கு முன்னும், பின்னும், நீங்கள் அல்லாஹ்வையன்றி (எவரையும்) வணங்காதீர்கள். (مِن بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ) 41:14; 46:21
- நிச்சயமாக, நீங்கள் பெண்களையன்றி ஆண்களிடம் இச்சையுடன் செல்கிறீர்கள்; மாறாக, நீங்கள் ஒரு மக்களாக (ஆகிவிட்டீர்கள்). (إِنَّكُمْ لَتَأْتُونَ الرِّجَالَ شَهْوَةً مِّن دُونِ النِّسَاءِ بَلْ أَنتُمْ قَوْمٌ) 7:81; 27:55
- அதில் என்றென்றும் இருப்பார்கள்; வானங்களும், பூமியும் இருக்கும் வரை, உமது இறைவன் நாடியதைத் தவிர. (خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالْأَرْضُ إِلَّا مَا شَاءَ رَبُّكَ) 11:107; 11:108
- வானங்களில் உள்ளவர்களும், பூமியில் உள்ளவர்களும் – அல்லாஹ் நாடியோரைத் தவிர. (مَن فِي السَّمَاوَاتِ وَمَن فِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ) 27:87; 39:68
- அதில் அவர்கள் பொன்னாலான வளைகளால் அலங்கரிக்கப்படுவார்கள்; முத்துக்களாலும்; அவர்களின் ஆடை அதில் பட்டு. (يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ مِن ذَهَبٍ وَلُؤْلُؤًا وَلِبَاسُهُمْ فِيهَا حَرِيرٌ) 22:23; 35:33
