- உயிர்த்தெழுதல் நாளில், அவர்கள் முரண்பட்டுக் கொண்டிருந்தவற்றில் அவர்களுக்கிடையே (அல்லாஹ்) தீர்ப்பு வழங்குவான். (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- அவர் கூறினார்: "என் சமூகத்தாரே! நான் என் இறைவனின் தெளிவான அத்தாட்சியில் இருந்தால் நீங்கள் என்ன நினைக்கிறீர்கள்?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- அது உங்கள் கைகள் முன்னரே அனுப்பிய காரணத்தால்; மேலும், அல்லாஹ் அடியார்களுக்கு அநியாயம் செய்பவனல்ல. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- இவ்வுலகில் அவர்களுக்கு இழிவும், மறுமையில் மாபெரும் வேதனையும் உண்டு. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- வானங்களில் உள்ளவையும், பூமியில் உள்ளவையும்; அல்லாஹ் போதுமான பாதுகாவலன். (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- எவர்கள் ஈமான் கொண்டு நற்செயல்கள் செய்தார்களோ அவர்களைத் தவிர; அவர்களுக்கு அறுந்துபோகாத கூலி உண்டு. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- நீ எனக்கு இணை கற்பிப்பதற்காக – உனக்கு அது பற்றி எந்த அறிவுமில்லை; ஆகவே, அவ்விருவருக்கும் நீ கீழ்படியாதே. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- நிச்சயமாக, இது ஒரு நினைவூட்டலாகும்; ஆகவே, விரும்பியவர் தன் இறைவனின் பாதையைத் தேர்வு செய்து கொள்க. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- இன்னும், எவர் நன்றி செலுத்துகிறாரோ, அவர் தனக்காகவே நன்றி செலுத்துகிறார்; எவர் நிராகரிக்கிறாரோ – நிச்சயமாக. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- எவர்கள் தொழுகையை நிலைநிறுத்துகிறார்களோ, ஸக்காத் வழங்குகிறார்களோ, இன்னும் மறுமையை உறுதியாக நம்புகிறார்களோ. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- இப்ராஹீம், இஸ்மாயீல், இஸ்ஹாக், யஅக்கூப் மற்றும் குலங்கள்; மேலும், மூசா மற்றும் ஈஸாவுக்கு வழங்கப்பட்டவை. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- கூட்டமாக, அவர்கள் அதை வந்தடையும் வரை; அதன் வாசல்கள் திறக்கப்படும்; அதன் காவலர்கள் அவர்களிடம் கூறுவார்கள். (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- அல்லாஹ் உங்கள் வீணான சத்தியங்களுக்காக உங்களைப் பிடிக்கமாட்டான்; எனினும், எதன் காரணமாக (அவன் உங்களைப் பிடிப்பான்?) (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- (அல்லாஹ்வின்) கருணை – அதைக் கண்டு அவர்கள் மகிழ்ந்தனர்; இன்னும், அவர்களின் கைகள் முன்னரே அனுப்பிய காரணத்தால் ஒரு தீமை அவர்களைச் சூழ்ந்தால். (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- அவற்றின் கீழே ஆறுகள் ஓடும்; அதில் என்றென்றும் இருப்பார்கள்; எத்தனை அழகான கூலி உழைப்போருக்கு! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- அல்லாஹ் வானங்களில் உள்ளவற்றையும், பூமியில் உள்ளவற்றையும் அறிகிறான்; மேலும், அல்லாஹ். (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- அல்லாஹ்வுக்குக் கீழ்ப்படியுங்கள்; தூதருக்கும் கீழ்ப்படியுங்கள்; நீங்கள் புறக்கணித்தால், அவர் மீது கடமை. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- அவர்களுக்கு அவர்களின் கூலி அவர்களின் இறைவனிடம் உண்டு; அவர்களுக்கு அச்சமுமில்லை; மேலும், அவர்கள். (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- மேலும், அவர்கள் கூறினர்: "நாங்கள் எலும்புகளும், மண்ணுமாக மாறிவிட்டால், புதிய படைப்பாக நாங்கள் உயிர்த்தெழுப்பப்படுவோமா?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- அல்லாஹ்வையன்றி அவர்களுக்கு எந்தப் பாதுகாவலனோ உதவியாளனோ அவர்கள் காணமாட்டார்கள். (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- நீ எவ்வளவு காலம் தங்கினாய்? அவர் கூறினார்: "நான் ஒரு நாள் அல்லது ஒரு நாளில் சிறிது பகுதி தங்கினேன்." அவர் கூறினார்: (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- நித்தியமாக – உயிர்த்தெழுதல் நாள் வரை. அல்லாஹ்வையன்றி எந்த இறைவன் உங்களுக்கு (இதை) கொண்டு வருவான்? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- எவர் நற்செயல் செய்கிறாரோ – ஆணாக இருந்தாலும் சரி, பெண்ணாக இருந்தாலும் சரி – இன்னும் அவர் முஃமினாக இருந்தால். (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- எவர்கள் அல்லாஹ்வின் பாதையைவிட்டுத் தடுக்கிறார்களோ, அதனை வளைந்ததாகக் காட்ட விரும்புகிறார்களோ, இன்னும் மறுமையை நிராகரிக்கிறார்களோ. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- நீங்கள் விரும்பும் இடத்தில் (செல்லுங்கள்); இந்த மரத்தை நெருங்காதீர்கள்; (அப்படிச் செய்தால்,) நீங்கள் அநியாயக்காரர்களில் ஆகிவிடுவீர்கள். (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- கூறுக: "என் சமூகத்தாரே! உங்கள் நிலையில் செயலாற்றுங்கள்; நான் (என் நிலையில்) செயலாற்றுகிறேன்; பின்னர் நீங்கள் அறிவீர்கள்." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- நிச்சயமாக, நஷ்டமடைந்தவர்கள் எவர்கள் என்றால், உயிர்த்தெழுதல் நாளில் தங்களையும், தங்கள் குடும்பத்தினரையும் நஷ்டப்படுத்திக் கொண்டவர்கள். அறிந்துகொள்ளுங்கள்! (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- எவர் நேர்வழி பெறுகிறாரோ, அவர் தனக்காகவே நேர்வழி பெறுகிறார்; எவர் வழிதவறுகிறாரோ, அவர் தனக்காகவே வழிதவறுகிறார்; மேலும், எவரும். (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- மேலும், நிராகரித்தவர்கள் கூறுகிறார்கள்: "ஏன் அவருக்கு அவருடைய இறைவனிடமிருந்து ஓர் அத்தாட்சி இறக்கப்படவில்லை?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- அவனே உங்களுக்கு இரவை (இளைப்பாறுதலுக்காக) உண்டாக்கினான்; பகலையும் பார்வைக்காக (உண்டாக்கினான்). நிச்சயமாக. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- எந்த வியாபாரமுமில்லை, எந்த நட்பும் இல்லாத நாள் வருவதற்கு முன்னர். (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- அவர்கள் சிந்திப்பதற்காக; அவர்களின் தோழருக்குப் பைத்தியமில்லை; அவர் அச்சமூட்டி எச்சரிப்பவர் மட்டுமே. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- அதில் என்றென்றும் இருப்பார்கள்; வேதனை அவர்களுக்கு இலேசாக்கப்படாது; அவர்களுக்கு அவகாசமும் வழங்கப்படாது. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- நாம் அவர்களில் சிலருக்கு அனுபவிக்கக் கொடுத்தவற்றின் பால் உம் கண்களை விரிவாக்காதீர். (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- மக்களுக்கு அவர்களின் பொருள்களில் நீங்கள் குறைக்காதீர்கள்; பூமியில் குழப்பம் செய்து கொண்டிருக்காதீர்கள். (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- இன்னும், அவர் பிறந்த நாளிலும், அவர் இறக்கும் நாளிலும், உயிருடன் எழுப்பப்படும் நாளிலும் சாந்தி உண்டாகட்டும். (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- என் சமூகத்தாரே! உங்கள் நிலையில் செயலாற்றுங்கள்; நான் (என் நிலையில்) செயலாற்றுகிறேன்; பின்னர் நீங்கள் அறிவீர்கள் – யார். (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- அல்லாஹ்வின் அனுமதியின்றி எந்தத் தூதரும் ஓர் அத்தாட்சியைக் கொண்டு வருவது இல்லை. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- பின்னர், ஒவ்வோர் ஆத்மாவும் தான் சம்பாதித்ததற்கு முழுமையாக வழங்கப்படும்; அவர்கள் அநியாயம் செய்யப்படமாட்டார்கள். (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- ஆணாக இருந்தாலும், பெண்ணாக இருந்தாலும், இன்னும் அவர் முஃமினாக இருந்தால் – அத்தகையோர் சொர்க்கத்தில் பிரவேசிப்பார்கள். (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- அவன் எந்தக் குழந்தையையும் எடுத்துக்கொள்ளவில்லை; இன்னும், ஆட்சியில் அவனுக்கு எந்தப் பங்காளியும் இல்லை. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- அல்லாஹ் எவரை நேர்வழி நடத்துகிறானோ, அவர் நேர்வழி பெற்றவர்; எவரை அவன் வழிதவறச் செய்கிறானோ, அவருக்கு நீர் எந்தப் பாதுகாவலனையும் காணமாட்டீர். (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- இதோ பார்! அவர்கள் உமக்கு எவ்வாறு உதாரணங்களைக் கூறுகிறார்கள்; அவர்கள் வழிதவறி விட்டனர்; இன்னும் (நேரான) வழியைக் கண்டுபிடிக்க மாட்டார்கள். (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- கூறுக: "நான் என் இறைவனுக்கு மாறு செய்தால், மாபெரும் நாளின் வேதனைக்கு நான் அஞ்சுகிறேன்." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- அவர்கள் இருவரின் மானங்களும் அவர்களுக்கு வெளிப்பட்டன; அவர்கள் சொர்க்கத்தின் இலைகளைக் கொண்டு தங்களை மூடிக்கொள்ளலானார்கள். (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- இன்னும், நீங்கள் உண்மையாளர்களாக இருந்தால், அல்லாஹ்வையன்றி நீங்கள் ஆற்றக்கூடியவர்களை அழையுங்கள். (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- பூமியிலுள்ள அனைத்தும், மேலும் அதனுடன் இன்னொரு மடங்கும் – அதனைக் கொண்டு (தங்களை) மீட்க. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- நாங்கள் உங்களுக்கு அளித்ததை வலுவுடன் பிடித்துக் கொள்ளுங்கள்; அதில் உள்ளவற்றை நினைவில் கொள்ளுங்கள் – நீங்கள் பயந்து நடக்கலாம். (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- உலக மக்களில் உங்களுக்கு முன் எவரும் செய்யாத மானக்கேடான காரியத்தை நீங்கள் செய்கிறீர்களா? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- அல்லாஹ்வுக்கே வானங்களிலும், பூமியிலும் உள்ள அனைத்தும் உரியவை; இன்னும், அல்லாஹ் (எல்லாவற்றையும்) உடையவனாக இருந்தான். (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- அவர்கள் செய்த தீமைகளின் பயன் அவர்களை வந்தடைந்தது; அவர்கள் ஏளனம் செய்து கொண்டிருந்தவை அவர்களைச் சூழ்ந்தன. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- உங்களிலிருந்தே (வந்த) ஒரு தூதர்; அவர் உங்களுக்கு நம் வசனங்களை ஓதிக் காட்டுகிறார்; உங்களைத் தூய்மைப்படுத்துகிறார்; இன்னும், உங்களுக்கு வேதத்தையும் ஞானத்தையும் கற்றுத் தருகிறார். (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- அதிலிருந்து பன்னிரண்டு ஊற்றுகள் (பெருகி ஓடின); ஒவ்வொரு கூட்டத்தினரும் தங்கள் நீர்நிலையை அறிந்து கொண்டனர். (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- யூகத்தைத் தவிர (வேறில்லை); நிச்சயமாக, யூகம் உண்மைக்கு எதிராக ஒரு பயனும் அளிக்காது. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- நான் அவனைச் சரியாக்கி, அவனில் எனது ஆன்மாவிலிருந்து ஊதும்போது, நீங்கள் அவனுக்குச் சிரம் பணிந்து வீழுங்கள். (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- வீட்டின் (மறுமையின்) முடிவு யாருக்கு உரியது? நிச்சயமாக, அநியாயக்காரர்கள் வெற்றி பெறமாட்டார்கள். (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- எவன் வானங்களையும், பூமியையும் படைத்தானோ, அவன் அவர்களைப் போன்றவர்களைப் படைக்க வல்லவன். (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- முஃமின் ஆண்களுக்கும், முஃமின் பெண்களுக்கும் – சொர்க்கங்கள், அவற்றின் கீழே ஆறுகள் ஓடும்; அதில் என்றென்றும் இருப்பார்கள். (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- நீர் அவர்களிடம் "வானங்களையும், பூமியையும் படைத்தவர் யார்?" என்று கேட்டால், அவர்கள் "அல்லாஹ்" என்று சொல்வார்கள். கூறுக: (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- இந்த குர்ஆனில் நாங்கள் மக்களுக்கு ஒவ்வொரு விதமான உதாரணங்களையும் தெளிவாக்கியுள்ளோம். (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- நம் தூதர்கள் லூத்திடம் வந்தபோது, அவர் அவர்களால் வருந்தினார்; மேலும் நெருக்கடிக்கு உள்ளானார்; இன்னும் கூறினார். (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- இன்னும், வானவர்களை நோக்கி: "ஆதமுக்குச் சிரம் பணியுங்கள்" என்று நாம் கூறியபோது; இப்லீஸ் தவிர மற்றவர்கள் சிரம் பணிந்தனர்; அவன் மறுத்தான். (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- நாம் பூமியை விரிவாக்கினோம்; அதில் உறுதியான மலைகளை நிலைநாட்டினோம்; அதில் ஒவ்வொரு விதமான (பயிர்களையும்) முளைக்கச் செய்தோம். (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
- அவர்கள் தீனை அவனுக்காகத் தூய்மைப்படுத்தி அல்லாஹ்விடம் பிரார்த்தனை செய்தனர்; இன்னும், அவன் அவர்களை (கடலிலிருந்து) பூமிக்கு (கரை) காப்பாற்றியபோது. (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
- அவர்களுக்கு கொதிக்கும் நீரிலிருந்து பானமும், துன்புறுத்தும் வேதனையும் உண்டு – அவர்கள் நிராகரித்துக் கொண்டிருந்த காரணத்தால். (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
