- அவர்கள் உங்களுக்கு இறக்கப்பட்டதிலும், உங்களுக்கு முன்னர் இறக்கப்பட்டதிலும் நம்பிக்கை கொள்கிறார்கள். (يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ) 2:4; 4:60; 4:162
- அல்லாஹ் வானத்திலிருந்து தண்ணீரை இறக்கியதை நீர் பார்க்கவில்லையா? (أَلَمْ تَرَ أَنَّ اللَّهَ أَنزَلَ مِنَ السَّمَاءِ مَاءً) 22:63; 35:27; 39:21
- அவன் ஓர் விஷயத்தை தீர்மானித்தால், அதற்கு "ஆகுக" என்று கூறுகிறான், அது ஆகிவிடுகிறது. (قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ) 3:47; 19:35; 40:68
- மத்யனுக்கு அவர்களுடைய சகோதரர் ஷுஐபை (அனுப்பினோம்). அவர் கூறினார்: "என் மக்களே! அல்லாஹ்வை வணங்குங்கள்." (وَإِلَى مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَاقَوْمِ اعْبُدُوا اللَّهَ) 7:85; 11:84; 29:36
- இது மறைவான செய்திகளில் ஒன்றாகும், நாம் அதை உங்களுக்கு வெளிப்படுத்துகிறோம், நீர் ... (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- அவர்களுடைய காலம் வந்துவிட்டால், அதை ஒரு மணிநேரம் கூட முன்னதாக்கவோ அல்லது பின்தள்ளவோ முடியாது. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- ஷைத்தானின் அடிச்சுவடுகளைப் பின்பற்ற வேண்டாம், நிச்சயமாக அவன் உங்களுக்கு பகிரங்கமான எதிரி. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- மனிதர்களில் சிலர், அறிவு இல்லாமல் அல்லாஹ்வைப் பற்றி வாதிடுகிறார்கள். (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- அல்லாஹ் அதைத் தான் நாடியவருக்கு வழங்குகிறான், அல்லாஹ் மகத்தான அருளாளன். (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- ஒவ்வொரு ஆத்மாவும் தான் சம்பாதித்ததற்கு முழுமையாக வழங்கப்படும், அவர்கள் அநியாயம் செய்யப்பட மாட்டார்கள். (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- அல்லாஹ் தடை செய்த ஓர் ஆத்மாவை, நியாயமான காரணமின்றி கொல்ல வேண்டாம். (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- அவன் ஓர் விஷயத்தை தீர்மானித்தால், அதற்கு "ஆகுக" என்று கூறுகிறான். (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- நரகத்தின் வாயில்களுக்குள் நுழையுங்கள், அதில் என்றென்றும் இருப்பீர்கள், இறுமாப்புக்காரர்களின் தங்குமிடம் மிகவும் கெட்டது! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- வேதத்தில் ஒரு பங்கு வழங்கப்பட்டவர்களை நீர் பார்க்கவில்லையா? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- அவர்களுக்கு சொர்க்கங்கள் உண்டு, அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் என்றென்றும் இருப்பார்கள். (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- என் மக்களே! நீங்கள் உங்கள் நிலையில் செயல்படுங்கள், நானும் செயல்படுகிறேன், நீங்கள் விரைவில் அறிவீர்கள். (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- எவர் அல்லாஹ்வையும் அவனுடைய தூதரையும் மீறுகிறாரோ, அவருக்கு நரக நெருப்பு உண்டு, அதில் என்றென்றும் இருப்பார். (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- அவர்களுடைய இதயங்களில் மூடிகள் உள்ளன, அவர்கள் அதைப் புரிந்து கொள்ளாதபடி, அவர்களுடைய காதுகளில் கனம். (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- எந்த ஒரு கிராமத்திற்கும் ஒரு எச்சரிப்பவர் வந்தால், அதன் வசதியுடையவர்கள் "நாங்கள்..." என்று கூறினர். (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- அவர்கள் கூறினர்: "அது என்னவென்று எங்களுக்குத் தெளிவுபடுத்துமாறு உமது இறைவனிடம் வேண்டுங்கள்." (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- அவர்கள் "அல்லாஹ்" என்று கூறுவார்கள். கூறுக: "எல்லாப் புகழும் அல்லாஹ்வுக்கே!" ஆனால் அவர்களில் பெரும்பாலோர் ... (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- அவருடைய மக்களின் பதில் "அவர்களை வெளியேற்றுங்கள்..." என்று கூறியதைத் தவிர வேறில்லை. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் என்றென்றும் நிலைத்திருப்பார்கள். அதுவே மகத்தான வெற்றி. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- அவர்கள் தங்கள் இறைவனின் நேர் வழியில் இருக்கிறார்கள், அவர்கள் தாம் வெற்றி பெற்றவர்கள். (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- எவருக்கு அவமானப்படுத்தும் வேதனை வருகிறதோ, எவர் மீது நிரந்தர வேதனை இறங்குகிறதோ. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- பூமியில் சுற்றிப் பாருங்கள், பொய்ப்பித்தவர்களின் முடிவு எவ்வாறு இருந்தது என்பதை. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- அவர்கள் தங்கள் கைகள் முன்னனுப்பியதன் காரணமாக அதை ஒருபோதும் விரும்ப மாட்டார்கள். அல்லாஹ் அநியாயக்காரர்களை நன்கு அறிந்தவன். (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- தனது பாதையில் வழிதவறியவர்களை அவனே நன்கு அறிவான், அவனே நன்கு அறிவான்... (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- நிச்சயமாக, அல்லாஹ் என்னுடைய இறைவன் மற்றும் உங்களுடைய இறைவன், ஆகவே அவனை வணங்குங்கள். இதுவே நேர் வழி. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- மனிதர்கள் மீது மிகுந்த அருளாளன், ஆனால் அவர்களில் பெரும்பாலோர் நன்றி செலுத்துவதில்லை. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- வானங்களையும், பூமியையும், அவற்றுக்கிடையே உள்ளவற்றையும், உண்மையுடனும் குறிப்பிட்ட காலத்துடனும் (படைத்தான்). (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- அவர்கள் தங்களுக்கு வாக்களிக்கப்பட்ட நாளைச் சந்திக்கும் வரை, அவர்களை விளையாடவும், மகிழவும் விட்டுவிடு. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- அவர்கள் நம்பிக்கை கொண்டவர்களைச் சந்திக்கும் போது "நாங்கள் நம்பிக்கை கொண்டோம்" என்று கூறுகிறார்கள். தனிமையில் இருக்கும் போது... (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- அவர்கள் தவ்ராத்தையும், இன்ஜீலையும், தங்கள் இறைவனிடமிருந்து இறக்கப்பட்டதையும் நிலைநாட்டினர். (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- அவர்களுக்கு முன்னால் உள்ளவற்றையும், அவர்களுக்குப் பின்னால் உள்ளவற்றையும் அறிவான், அவர்கள் அதைச் சூழ்ந்து கொள்ள மாட்டார்கள்... (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- அவனே வானங்களையும், பூமியையும் ஆறு நாட்களில் படைத்தான். (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- நிச்சயமாக, இதில் உங்களுக்கு ஓர் அத்தாட்சி இருக்கிறது, நீங்கள் நம்பிக்கை கொண்டவர்களாக இருந்தால். (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- வழிகாட்டுதல் அவர்களிடம் வந்தபோது, மக்கள் நம்பிக்கை கொள்வதைத் தடுத்தது எது? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- அவர்கள் அல்லாஹ்வுக்கு இணைகளை ஆக்கி, அவனுடைய பாதையில் இருந்து வழிகெடுக்கின்றனர். கூறுக: "சுகம் அனுபவியுங்கள்..." (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- தம்மில் இருந்தே ஓர் எச்சரிப்பவர் வந்ததை அவர்கள் வியந்தனர், நிராகரித்தவர்கள் கூறினர்: "இது..." (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- நிச்சயமாக, உமது இறைவன் தனது பாதையில் வழிதவறியவர்களை நன்கு அறிவான். (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- தனது செல்வத்தை மக்களுக்குக் காட்டுவதற்காக செலவு செய்து, அல்லாஹ்வை நம்பாதவனைப் போன்று. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- நாம் உங்களுக்கு அளித்ததிலிருந்து, (வேதனை) வருவதற்கு முன்னர் செலவு செய்யுங்கள். (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- வானங்களில் உள்ளவற்றையும், பூமியில் உள்ளவற்றையும் உங்களுக்கு கட்டுப்படுத்திக் கொடுத்தான். (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- நீங்கள் எங்களை எதன்பால் அழைக்கிறீர்களோ, அதைப் பற்றி நாங்கள் சந்தேகத்தில் இருக்கிறோம். (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- நிச்சயமாக, உமது இறைவன் தான் நாடியவருக்கு வாழ்வாதாரத்தை விசாலமாக்குகிறான், இறுக்குகிறான். நிச்சயமாக, அவன்... (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- வானங்கள் மற்றும் பூமி ஆகியவற்றின் இறைவனும், அவற்றுக்கிடையே உள்ளவற்றின் இறைவனும், நீங்கள் உறுதியாக நம்புபவர்களாக இருந்தால். (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- நாங்கள் அல்லாஹ்வின் மீதும், எங்களுக்கு இறக்கப்பட்டதன் மீதும், இறக்கப்பட்டதன் மீதும் நம்பிக்கை கொண்டோம்... (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- அநியாயம் செய்தவர்களைப் பயங்கரமான சப்தம் பற்றிக்கொண்டது, அவர்கள் தங்கள் வீடுகளில் முடங்கிக் கிடந்தனர். (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- அவர்கள் தங்களைப் பற்றி என்ன செய்தாலும் உங்கள் மீது குற்றமில்லை. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- உமது இறைவன் தனது பாதையில் வழிதவறியவர்களை நன்கு அறிவான், அவன்... (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- தனது கட்டளையின் மூலம் (அருட்கொடையான) ஆன்மாவைத் தான் நாடிய தனது அடியார்களுக்கு வழங்குகிறான். (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- மர்யமின் மகன் ஈஸாவுக்கு நாம் தெளிவான அத்தாட்சிகளை வழங்கினோம், அவரை பரிசுத்த ஆவியால் பலப்படுத்தினோம். (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- உயிர்த்தெழுதல் நாளில் அவர்களுக்கிடையே, அவர்கள் முரண்பட்டுக் கொண்டிருந்த விஷயத்தில் தீர்ப்பளிக்கும் பொருட்டு. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- அதன் மேல்பகுதியை கீழ்ப்பகுதியாக ஆக்கினோம், அதன் மீது சுட்ட களிமண் கற்களை பொழிந்தோம். (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- நீர் அவர்களை எச்சரித்தாலும், எச்சரிக்காவிட்டாலும் அவர்களுக்கு சமமே, அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள். (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- மனிதர்களைத் தவிர, நீங்கள் உண்மையாளர்களாக இருந்தால் மரணத்தை விரும்புங்கள். (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- அல்லாஹ்வை வணங்குங்கள், அவனைத் தவிர உங்களுக்கு வேறு இறைவன் இல்லை. நீங்கள் அஞ்சமாட்டீர்களா? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- நாம் அவர்களுக்கு வாக்களித்தவற்றில் சிலவற்றை உமக்குக் காண்பித்தாலும், அல்லது உம்மை மரணிக்கச் செய்தாலும், நம்மிடமே அவர்களுடைய திரும்புதல்... (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- அவர்கள் கூறினர்: "நாங்கள் இறந்து, மண்ணாகவும், எலும்புகளாகவும் ஆன பின்னர், நாங்கள் நிச்சயமாக உயிர்ப்பிக்கப்படுவோமா?" (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- நிச்சயமாக, அருள் அல்லாஹ்வின் கையில் உள்ளது, அதை அவன் தான் நாடியவருக்கு வழங்குகிறான், அல்லாஹ்... (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- மறைவானவற்றையும், வெளிப்படையானவற்றையும் அறிந்தவனிடம், அவன் நீங்கள் செய்து கொண்டிருந்தவற்றை உங்களுக்கு அறிவிப்பான். (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- நம்பிக்கை கொண்டவர்களே! அல்லாஹ் உங்கள் மீது காட்டிய அருளை நினைவுகூருங்கள், அப்போது... (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- உமக்கு முன்னர் நாம் ஆண்களைத் தவிர (வேறு எவரையும்) தூதர்களாக அனுப்பவில்லை, அவர்களுக்கு நாம் வெளிப்படுத்தினோம். (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- அவனுடைய பாவங்களை மன்னித்து, அவனை சொர்க்கங்களில் பிரவேசிக்கச் செய்வான், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும். (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- நோயாளியாகவோ அல்லது பயணத்திலோ இருந்தால், பிற நாட்களில் (நோன்பு) எண்ணிக்கை. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- அவர்கள் வெறும் ஊகத்தையே பின்பற்றுகிறார்கள், அவர்கள் வெறும் பொய்யான கற்பனைகளையே செய்கிறார்கள். (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- அல்லாஹ்வையும், இறுதி நாளையும் எதிர்பார்ப்பவருக்கு நல்ல முன்மாதிரி. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- நாம் வானங்களையும், பூமியையும், அவற்றுக்கிடையே உள்ளவற்றையும் உண்மையுடன் தவிர (வீணாக) படைக்கவில்லை. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- உமது கையை உமது சட்டைப் பையில் போடுங்கள், அது குற்றமின்றி வெண்மையாக வெளிவரும். (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- தான் விரும்பியவர்களுக்கு தனது அருளைச் சிறப்பிக்கிறான், அல்லாஹ் மகத்தான அருளாளன். (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- அல்லாஹ்வுக்கு வானங்கள் மற்றும் பூமியின் ஆட்சி உண்டு என்பதை நீர் அறியவில்லையா? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- நீங்கள் உங்களுக்காக முன்னனுப்பும் எந்த நன்மையையும், அதை அல்லாஹ்விடத்தில் காண்பீர்கள். (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- நீர் எங்கிருந்து புறப்பட்டாலும், உமது முகத்தைப் புனிதப் பள்ளிவாசலை நோக்கித் திருப்புங்கள். (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- இவர்களுக்கு முன்னரும் (இது) நடந்துவிட்டது, அல்லாஹ்வின் வழக்கத்தில் நீர் எந்த மாற்றத்தையும் காண மாட்டீர். (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- வானங்களில் உள்ளவையும், பூமியில் உள்ளவையும் எவனுக்குச் சொந்தமோ அவனை. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- எந்தப் பெண்ணும் கர்ப்பமாவதும், பிரசவிப்பதும் அவனுடைய அறிவில் இல்லாமல் இல்லை. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- இரவு, மேலும் சூரியனையும், சந்திரனையும் வசப்படுத்தினான், ஒவ்வொன்றும் குறிப்பிட்ட காலத்திற்கு இயங்குகின்றன. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் என்றென்றும் இருப்பார்கள், அதுவே ...க்கான கூலி. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- அவர் கூறினார்: "இல்லை, உங்கள் மனங்கள் உங்களுக்கு ஒரு விஷயத்தை அழகாக்கின. பொறுமை அழகானது." (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- வானங்களில் உள்ளவையும், பூமியில் உள்ளவையும், மேலும் அல்லாஹ் ... (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- அவர்களிடம் யாரேனும் ஓர் தூதர் வந்தால், அவர்கள் அவரை ஏளனம் செய்தார்கள். (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- அவர்கள் கூறினர்: "மூஸாவே! நீ எறிகிறாயா அல்லது நாங்கள் எறிகிறோமா?" (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- உங்களை அவன் மரணிக்கச் செய்கிறான், உங்களில் சிலர் மிகவும் இழிந்த வயதுக்குத் திருப்பப்படுகிறார்கள், அதனால்... (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- அவர்களுக்கு அவர்களுடைய இறைவனிடம் சொர்க்கங்கள் உண்டு, அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் என்றென்றும் இருப்பார்கள். (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- அவர்களின் இதயங்களின் மீது மூடிகளை வைத்தோம், அவர்கள் அதைப் புரிந்து கொள்ளாதபடி, மேலும் அவர்களின் காதுகளில் ... (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- நிச்சயமாக, அல்லாஹ்வின் வாக்குறுதி உண்மையானது, ஆனால் அவர்களில் பெரும்பாலோர் அறிய மாட்டார்கள். (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- அது ஏனெனில் அவர்கள் அல்லாஹ்வையும், அவனுடைய தூதரையும் எதிர்த்தார்கள், எவர் அல்லாஹ்வை எதிர்க்கிறாரோ... (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- அவன் அவர்களை அழைக்கும் நாளில், "நீங்கள் கற்பனை செய்து கொண்டிருந்த என்னுடைய இணைகள் எங்கே?" என்று கூறுவான். (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- வானங்களையும், பூமியையும் படைத்த அல்லாஹ்வை அவர்கள் பார்க்கவில்லையா? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- உன்னை மண்ணிலிருந்தும், பின்னர் ஒரு துளியிலிருந்தும், பின்னர் ... படைத்தவனை (எச்சரிக்கிறேன்). (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- அவர்கள் கூறுவார்கள்: "எங்கள் இறைவனே! நீ எங்களுக்கு ஓர் தூதரை அனுப்பியிருக்கக் கூடாதா? நாங்கள் உன்னுடைய அத்தாட்சிகளைப் பின்பற்றியிருப்போமே!" (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- பின்னர், அவர்களுடைய திரும்புதல் அவர்களுடைய இறைவனிடமே, அவர்கள் செய்து கொண்டிருந்ததை அவர்களுக்கு அறிவிப்பான். (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- இதைப் பற்றி அவர்களுக்கு எந்த அறிவும் இல்லை, அவர்கள் வெறும் ... (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- நாங்கள் எங்கள் மூதாதையர்களை ஒரு மார்க்கத்தில் கண்டோம், நாங்கள் அவர்களுடைய அடிச்சுவடுகளில் இருக்கிறோம். (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- வேதம் வழங்கப்பட்டவர்கள், அது அவர்களிடம் வந்த பின்னரே... (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- இப்ராஹீம் கூறியபோது: "என் இறைவனே! இந்த ஊரைப் பாதுகாப்பானதாக ஆக்கு." (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- உங்களுக்கு காதுகள், கண்கள் மற்றும் இதயங்களை அமைத்துக் கொடுத்தான், ஆனால் நீங்கள் மிகவும் குறைவாகவே நன்றி செலுத்துகிறீர்கள். (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- அல்லாஹ்வுடைய வசனங்களைப் பற்றி, அவர்களுக்கு வந்த எந்த ஆதாரமும் இல்லாமல் வாதிடுபவர்கள். (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- எனவே, இப்ராஹீமின் மார்க்கத்தைப் பின்பற்றுங்கள், அவர் ஏகத்துவவாதியாக இருந்தார், அவர் இணைவைப்பவர்களில் இருந்ததில்லை. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- ஃபிர்அவ்னின் குடும்பத்திலிருந்து உங்களை நாம் விடுவித்தோம், அவர்கள் உங்களைக் கொடூரமான வேதனைக்கு உட்படுத்தினர். (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- அதுவே நேரான மார்க்கம், ஆனால் பெரும்பாலான மக்கள் அறிய மாட்டார்கள். (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- அல்லாஹ் உங்களுக்கு பூமியில் உள்ளவற்றை வசப்படுத்தித் தந்ததை நீர் பார்க்கவில்லையா? (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- நிராகரித்தவர்கள் கூறினர்: "இது வெளிப்படையான சூனியம் தவிர வேறில்லை." (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- நமது தெளிவான வசனங்கள் அவர்களுக்கு ஓதிக்காட்டப்படும் போது, நிராகரித்தவர்கள் கூறுகிறார்கள்... (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- நிரந்தர சொர்க்கங்கள், அவற்றின் கீழே ஆறுகள் ஓடிக்கொண்டிருக்கும், அதில் என்றென்றும் இருப்பார்கள். (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- அவன் விரும்பியதை, நிச்சயமாக அல்லாஹ் அனைத்து விஷயங்களிலும் ஆற்றல் உடையவன். (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- அவன் உங்கள் பாவங்களை மன்னித்து, ஒரு குறிப்பிட்ட காலம் வரை உங்களைத் தாமதப்படுத்தும் பொருட்டு. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- எங்கள் மூதாதையர்கள் வணங்கியதிலிருந்து எங்களைத் திருப்ப விரும்புகிறீர்கள். (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- உமது இறைவன் வானவர்களிடம் கூறியபோது: "நான் மனிதனை ... படைக்கிறேன்." (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- அவனே, தனது அருளுக்கு முன்னதாக காற்றுகளை நற்செய்தியாக அனுப்புகிறான். (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- கூறுக: "பூமியில் பயணம் செய்து, ...னின் முடிவு எவ்வாறு இருந்தது என்று பாருங்கள்." (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- நிச்சயமாக, வானங்கள் மற்றும் பூமியின் படைப்பிலும், இரவு மற்றும் பகலின் மாற்றத்திலும் (அத்தாட்சிகள் உள்ளன). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- அல்லாஹ்வுக்கு அழகான கடன் கொடுப்பவர் யார்? அதனால் அவன் அதைப் பெருக்கி வழங்குவான். (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- எனவே, அல்லாஹ் இறக்கியதைக் கொண்டு அவர்களுக்கிடையே தீர்ப்பு செய்யுங்கள், அவர்களுடைய மன இச்சைகளைப் பின்பற்ற வேண்டாம். (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- அவர்கள் எதை எதிர்பார்க்கிறார்கள்? வானவர்கள் அல்லது உமது இறைவன் (வேதனையுடன்) வருவதைத் தவிர? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- நிச்சயமாக, அல்லாஹ்வின் மீது பொய்யை இட்டுக்கட்டுபவர்கள் வெற்றி பெற மாட்டார்கள். (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- ஃபிர்அவ்னின் குடும்பத்தினருடைய முறை மற்றும் அவர்களுக்கு முன்னோர்களைப் போன்று, அவர்கள் நமது அத்தாட்சிகளைப் பொய்ப்பித்தனர். (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- நற்செயல்கள் செய்யும் நம்பிக்கையாளர்களுக்கு அவர்களுக்கு நல்ல கூலி உண்டு என்று நற்செய்தி கூறுகிறான்... (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- அல்லாஹ் தனது அடியார்களில் தான் நாடியவருக்கு வாழ்வாதாரத்தை விசாலமாக்குகிறான், இறுக்குகிறான். (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- மறைவானவற்றையும், வெளிப்படையானவற்றையும் அறிந்தவனிடம் நீங்கள் திருப்பப்படுவீர்கள், நீங்கள் செய்து கொண்டிருந்தவற்றை அவன் உங்களுக்கு அறிவிப்பான். (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- அல்லாஹ்வின் வேதத்தில், உறவினர்கள் ஒருவருக்கொருவர் மிகவும் நெருங்கிய உரிமை உடையவர்கள். (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — கட்டாயம் (செய்ய வேண்டும்; விட்டுவிடுவது பாவம்)
- mustahabb / mandub (مستحب / مندوب) — பரிந்துரைக்கப்பட்டது (செய்தால் கூலி, விட்டுவிட்டால் பாவம் இல்லை)
- mubah (مباح) — நடுநிலையான / அனுமதிக்கப்பட்டது (கூலி அல்லது பாவம் இல்லை)
- makruh (مكروه) — விரும்பத்தகாதது (ஊக்கப்படுத்தப்படவில்லை, ஆனால் செய்தால் பாவம் இல்லை)
- haram (حرام) — தடை செய்யப்பட்டது (செய்வது பாவம்)
- halal (حلال, அனுமதிக்கப்பட்ட / சட்டபூர்வமான) — முபாஹ் மற்றும் முஸ்தஹப் இரண்டையும் உள்ளடக்கியது — தடை செய்யப்படாத அனைத்தும்
- அல்லாஹ்வை மட்டுமே வணங்குங்கள், அவனிடம் உதவி தேடுங்கள். 1:5
- அல்லாஹ்வை மட்டுமே வணங்குங்கள் 2:21
- அல்லாஹ்வுக்கு எந்த இணையும் சேர்க்காதீர்கள் 2:22
- அல்லாஹ் மன்னிப்பவன் (பாவமன்னிப்பை ஏற்பவன்); அவன் ஆதம் (عَلَيْهِ ٱلسَّلَامُ) அவர்களின் பாவமன்னிப்பை ஏற்றுக்கொண்டான். 2:37
- சத்தியத்தை பொய்யுடன் கலக்காதீர்கள், சத்தியத்தை மறைக்காதீர்கள். 2:42
- தொழுகையை (தினசரி தொழுகைகளை) நிலைநாட்டுங்கள், ஜகாத்தை (தானத்தை) கொடுங்கள். 2:43
- மற்றவர்களுக்கு நன்மையை கட்டளையிடும் முன் அதை நீங்களே கடைப்பிடியுங்கள் 2:44
- உங்கள் எல்லா விஷயங்களிலும் அல்லாஹ்விடம் உதவி தேடுங்கள் 2:45
- ஊழலில் ஈடுபடாதீர்கள் அல்லது பரப்பாதீர்கள் 2:60
- மக்கள் வழிபாட்டு இடங்களுக்குச் செல்வதை தடுக்காதீர்கள் 2:114
- பள்ளிவாசலின் புனிதத்தை மதியுங்கள். உங்கள் தொழுகை இடங்களை சுத்தமாகவும் தூய்மையாகவும் வைத்திருங்கள் 2:125
- அல்லாஹ்வை (தொழுகை, தஸ்பீஹ் மூலம்) நினைவுகூருங்கள்; அவன் உங்களை நினைவுகூறுவான்; அவனுக்கு நன்றி செலுத்துங்கள். 2:152
- துன்பங்களில் பொறுமையை கடைபிடியுங்கள் 2:153
- ஷைத்தானின் (சாத்தானின்) அடிச்சுவடுகளைப் பின்பற்றாதீர்கள்; அவன் வெளிப்படையான எதிரி. 2:168
- யாரையும் குருட்டுத்தனமாக பின்பற்றாதீர்கள் 2:170
- அனைத்து பொறுப்புகளையும் பேணி நிறைவேற்றுங்கள். உங்கள் மதக் கடமைகளை உண்மையுடன் நிறைவேற்றுங்கள். உங்கள் சத்தியங்களையும் உடன்படிக்கைகளையும் நிறைவேற்றுங்கள். வாக்குறுதிகளை, குறிப்பாக அல்லாஹ்வுக்கு செய்தவற்றைக் காப்பாற்றுங்கள். தேவையுள்ளவர்களுக்கு உதவுங்கள், துன்பங்களைப் போக்குங்கள். அல்லாஹ்வின் அருளை இழக்கச் செய்யும் பாவங்களைச் செய்வதைத் தவிருங்கள். ஆணவம் உங்களை அநீதிக்கு இட்டுச் செல்ல அனுமதியாதீர்கள் 2:177
- கிசாஸில் (தண்டனையில் சமத்துவச் சட்டத்தில்) உங்களுக்கு உயிர் இருக்கிறது. 2:179
- ரமழான் மாதத்தில் நோன்பு நோற்பீர்களாக. முத்தக்கீன் (இறையச்சமுடையவர்கள்) ஆவதற்கு நியமிக்கப்பட்ட நோன்பைக் கடைப்பிடியுங்கள். 2:183
- ஹிதாயத்தின் இறுதி ஆதாரமாக குர்ஆனை மதியுங்கள் 2:185
- ஒருவரின் சொத்தை அநியாயமாகச் சாப்பிடாதீர்கள்; (உங்கள் வழக்குகளைத் தாக்கல் செய்வதற்கு முன்) நீதிபதிகளுக்கு இலஞ்சம் கொடுக்காதீர்கள். 2:188
- மற்றவர்களை, வார்த்தையாலோ அல்லது செயலாலோ, ஒடுக்காதீர்கள். ஒருபோதும் ஆக்கிரமிப்பாளராக சண்டையிடாதீர்கள்; பாதுகாப்பிற்காக மட்டுமே சண்டையிடுங்கள் 2:190
- அனாதைகளைப் பாதுகாக்கவும். அனாதைகளைப் பொறுத்தவரை, அவர்களின் சொத்தில் நேர்மையாக வேலை செய்யுங்கள், அவர்களின் சொத்தை விழுங்காதீர்கள். 2:220
- பாவமன்னிப்பு கேட்டு தவ்பா செய்யுங்கள். மாதவிடாய் காலத்தில் உடலுறவு கொள்ளாதீர்கள். (உடல் மற்றும் ஆன்மீக) தூய்மையை பராமரியுங்கள் 2:222
- உங்கள் குடும்பத்தினருக்கான உங்கள் பொறுப்புகளை நிறைவேற்றுங்கள் 2:233
- தலைவர்களை அவர்களின் தகுதியின் அடிப்படையில் தேர்ந்தெடுங்கள் 2:247
- மதத்தில் வற்புறுத்தல் இல்லை 2:256
- செல்வத்தை தானத்தில் செலவழியுங்கள். செல்வம் மற்றும் நேரத்தில் தாராளமாக இருங்கள் 2:261
- உங்கள் கொடையைப் பற்றி பெருமைப்படுவதன் மூலம் தானத்தை பயனற்றதாக்காதீர்கள் 2:264
- ஷைத்தான் உங்களுக்கு வறுமையை அச்சுறுத்துகிறான்; மேலும் அவன் உங்களுக்கு ஃபஹ்ஷாவை (தீய செயல்கள், தவறான உடலுறவு, பாவங்கள்) செய்யும்படி கட்டளையிடுகிறான். 2:268
- தேவையுள்ளவர்களை தேடி உதவுங்கள் 2:273
- வட்டி அல்லது வட்டித் தொழிலில் ஈடுபடாதீர்கள். வட்டி அடிப்படையிலான செல்வத்தை உண்ணாதீர்கள். ரிபா (வட்டி) உண்ணாதீர்கள். 2:275
- கடனாளி கடினமான நேரத்தில் இருந்தால் திரும்ப செலுத்த அதிக நேரம் கொடுங்கள் 2:280
- வணிக பரிவர்த்தனைகளில் உங்கள் வார்த்தையைக் காப்பாற்றுங்கள். உங்கள் நிதி விஷயங்களில் உண்மையாக இருங்கள். உங்கள் அனைத்து உறுதிமொழிகளிலும் நேர்மையுடன் செயல்படுங்கள். நீங்கள் ஒரு குறிப்பிட்ட காலத்திற்கு கடன் ஒப்பந்தம் செய்யும்போது, அதை எழுதுங்கள். நீங்கள் ஒரு வணிக ஒப்பந்தம் செய்யும் போதெல்லாம் சாட்சிகளை எடுத்துக் கொள்ளுங்கள். 2:282
- அனைத்து பொறுப்புகளையும் பேணி நிறைவேற்றுங்கள் 2:283
- அருளப்பட்ட வேதங்களிலும், அனைத்து நபிமார்களிலும் நம்பிக்கை கொள்ளுங்கள் 2:285
- அல்லாஹ் எந்த ஆன்மாவையும் அதன் சக்திக்கு அதிகமாக சுமைப்படுத்துவதில்லை. அவர்கள் சம்பாதித்த (நன்மைக்கு) பிரதிபலன் பெறுவார்கள்; (தீமைக்கு) தண்டிக்கப்படுவார்கள். அல்லாஹ் எந்த ஆன்மாவையும் அதன் சக்திக்கு அதிகமாக சுமைப்படுத்துவதில்லை; நாமும் அப்படி செய்யக்கூடாது. துன்பத்திலும் அல்லாஹ்வின் திட்டத்தில் நம்பிக்கை வையுங்கள் 2:286
- எவர் வாக்குறுதிகளை நிறைவேற்றி, அல்லாஹ்வுக்கு அஞ்சுகிறாரோ, நிச்சயமாக அல்லாஹ் இறையச்சமுடையவர்களை நேசிக்கிறான். 3:76
- உங்களால் முடிந்தால் ஹஜ்ஜை (புனிதப் பயணத்தை) செய்யுங்கள் 3:97
- பிரிந்து விடாதீர்கள் 3:103
- நன்மையை கட்டளையிட்டு, தீமையை தடுங்கள். உங்கள் சமூகத்தில் நீதியை ஊக்குவியுங்கள். மற்றவர்களை அல்லாஹ்வின் நினைவிற்கு அழையுங்கள் 3:104
- இறை நம்பிக்கையாளர்கள் அல்லாஹ்விடம் மட்டுமே நம்பிக்கை வைக்க வேண்டும். 3:122
- ரிபாவை (வட்டியை) உண்ணாதீர்கள். 3:130
- கருணை பெற அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் கீழ்ப்படியுங்கள். 3:132
- அல்லாஹ், செல்வத்திலும், துன்பத்திலும் (அல்லாஹ்வின் பாதையில் – தானம், தருமம்) செலவு செய்பவர்களையும், கோபத்தை அடக்குபவர்களையும், மனிதர்களை மன்னிப்பவர்களையும் நேசிக்கிறான். 3:134
- கோபத்தை அடக்குங்கள். 3:134
- மற்றவர்களின் தவறுகளை மன்னியுங்கள் 3:135
- பேச்சில் முரட்டுத்தனமாக இருக்காதீர்கள். உங்களிடமிருந்து வேறுபட்டவர்களிடம் பொறுமையாக இருங்கள் 3:159
- அல்லாஹ் உங்களுக்கு உதவினால், உங்களை யாரும் வெல்ல முடியாது; அவன் உங்களைக் கைவிட்டால், அவனுக்குப் பின் யார் உங்களுக்கு உதவ முடியும்? 3:160
- ஒவ்வொருவரும் மரணத்தைச் சுவைப்பார்கள். மறுமை நாளில் மட்டுமே உங்கள் கூலி முழுமையாக வழங்கப்படும். 3:185
- இயற்கையின் அற்புதங்கள் மற்றும் இந்த பிரபஞ்சத்தின் படைப்பு பற்றி ஆழமாக சிந்தியுங்கள். கடவுள் இந்த பிரபஞ்சத்தை பொருள் மற்றும் நோக்கத்துடன் படைத்துள்ளார் என்பதை அறிந்து கொள்ளுங்கள் 3:191
- ஆண்களுக்கும் பெண்களுக்கும் அவர்களின் செயல்களுக்கு சமமான கூலி உண்டு 3:195
- தங்கள் இறைவனுக்கு அஞ்சுபவர்களுக்கு, (சொர்க்கத்தில்) கீழே ஆறுகள் ஓடும் தோட்டங்கள் உள்ளன; அங்கு அவர்கள் என்றென்றும் தங்கியிருப்பார்கள்; இது அல்லாஹ்விடமிருந்து வரும் விருந்தோம்பல். 3:198
- ஒவ்வொரு செயலிலும் அல்லாஹ்வின் திருப்திக்காக எப்போதும் முயற்சி செய்யுங்கள். 3:200
- உங்கள் இறைவனுக்கு கீழ்ப்படியுங்கள், அவனுக்கு அஞ்சுங்கள், மேலும் (உறவுகளைத் துண்டிக்காதீர்கள்) உறவினர்களுடன். 4:1
- அனாதைகளுக்கு அவர்களின் சொத்தை கொடுங்கள்; உங்கள் கெட்ட பொருட்களை அவர்களின் நல்ல பொருட்களுடன் பரிமாறிக்கொள்ளாதீர்கள்; அவர்களின் பொருட்களை உங்கள் பொருட்களுடன் சேர்த்து விழுங்காதீர்கள். 4:2
- நீங்கள் மணக்கும் பெண்களுக்கு அவர்களின் மஹ்ரை (திருமணத்தின் போது கணவன் மனைவிக்கு கொடுக்க வேண்டிய கட்டாய பரிசுத் தொகை) மனமுவந்து கொடுங்கள். 4:4
- அனாதைகளின் உரிமைகளைப் பாதுகாக்கவும் 4:6
- இறந்தவரின் சொத்து அவரது குடும்ப உறுப்பினர்களிடையே பங்கிடப்பட வேண்டும். பெண்களுக்கு வாரிசுரிமை உண்டு 4:7
- அனாதைகளின் சொத்தை அநியாயமாக உண்ணாதீர்கள் 4:10
- வாரிசு தொடர்பான கட்டளைகளுக்குக் கீழ்ப்படியுங்கள் 4:11
- பெண்களை அவர்களின் விருப்பத்திற்கு எதிராக வாரிசாகப் பெறுவது தடை செய்யப்பட்டுள்ளது, நீங்கள் அவர்களிடம் கடுமையாக நடந்து கொள்ளக்கூடாது. அவர்களுடன் (மனைவிகளுடன்) கண்ணியமாக வாழுங்கள். பெண்களின் உரிமைகளை மதித்து கடைப்பிடியுங்கள். உங்கள் துணையுடன் அன்புடனும் இரக்கத்துடனும் நடந்து கொள்ளுங்கள். பெண்களுடன் கண்ணியத்துடனும் நீதியுடனும் நடந்து கொள்ளுங்கள் 4:19
- இரத்த உறவினர்களை மணக்காதீர்கள் 4:23
- உங்களை நீங்களே (அல்லது ஒருவரை ஒருவர்) கொலை செய்து கொள்ளாதீர்கள். நிச்சயமாக அல்லாஹ் உங்கள் மீது மிக்க கருணையாளன். ஒருவரின் சொத்தை அநியாயமாக உண்ணாதீர்கள் 4:29
- நீங்கள் தடை செய்யப்பட்ட பெரும் பாவங்களைத் தவிர்த்தால், அல்லாஹ் உங்கள் (சிறிய) பாவங்களை மன்னித்து, உங்களை ஒரு உன்னத பிரவேசத்தில் (அதாவது சொர்க்கத்தில்) பிரவேசிக்கச் செய்வான். 4:31
- அல்லாஹ் உங்களில் சிலருக்கு மற்றவர்களை விட அதிகமாக கொடுத்துள்ள விஷயங்களை ஆசைப்படாதீர்கள். பொறாமை மற்றும் பேராசையைத் தவிருங்கள் 4:32
- ஆண்கள் பெண்களின் பாதுகாவலர்கள் மற்றும் பராமரிப்பாளர்கள்; ஏனெனில் அல்லாஹ் அவர்களில் சிலரை மற்றவர்களை விட உயர்த்தியுள்ளான்; மேலும் அவர்கள் (அவர்களைப் பராமரிக்க) தங்கள் சொத்திலிருந்து செலவு செய்கிறார்கள். ஆண் குடும்பத்தின் பாதுகாவலரும் ஆதரவாளருமாவான். 4:34
- அல்லாஹ்வை வணங்குங்கள், அவனுக்கு எதையும் இணையாக்காதீர்கள்; பெற்றோர்களுக்கு, உறவினர்களுக்கு, அனாதைகளுக்கு, ஏழைகளுக்கு, அண்டை வீட்டாருக்கு, உங்கள் அருகில் உள்ள தோழருக்கு, நீங்கள் சந்திக்கும் வழிப்போக்கருக்கு, மேலும் உங்கள் வலது கைக்கு சொந்தமான (அடிமைகளுக்கு) நன்மை செய்யுங்கள். அல்லாஹ் பெருமை அடிப்பவர்களையும், தற்பெருமை கொண்டவர்களையும் விரும்புவதில்லை. மற்றவர்களுக்கு நல்லவர்களாக இருங்கள். பலவீனமானவர்களுக்கு இரக்கம் காட்டுங்கள். குடும்ப உறவுகளை பேணுங்கள் மற்றும் உறவினர்களை கௌரவியுங்கள். 4:36
- கருமியாக இருக்காதீர்கள் 4:37
- அல்லாஹ் தனக்கு இணை கற்பிப்பதை மன்னிக்க மாட்டான்; ஆனால் இதைத் தவிர (வேறு எதையும்) அவன் விரும்பியவருக்கு மன்னிக்கிறான். 4:48
- மற்றவர்களுக்கு பொறாமைப்படாதீர்கள் 4:54
- அல்லாஹ் உங்களுக்கு கட்டளையிடுகிறான்: நீங்கள் பொறுப்புகளை அவர்களுக்கு உரியவர்களிடம் ஒப்படைக்க வேண்டும். மக்களிடையே நீங்கள் தீர்ப்பளிக்கும்போது, நீதியுடன் தீர்ப்பளியுங்கள். 4:58
- அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் கீழ்ப்படியுங்கள். உங்களிடையே அதிகாரம் உள்ளவர்களுக்கு மரியாதை கொடுங்கள் 4:59
- பலவீனமானவர்களையும், பாதிக்கப்படக்கூடியவர்களையும் ஒடுக்காதீர்கள் 4:75
- உங்களுக்கு வரும் நன்மையானது அல்லாஹ்விடமிருந்து வருகிறது; ஆனால் உங்களுக்கு ஏற்படும் தீமையானது உங்களிடமிருந்தே வருகிறது. 4:79
- எவர் தூதருக்கு (முஹம்மது ﷺ) கீழ்ப்படிகிறாரோ, அவர் அல்லாஹ்வுக்குக் கீழ்ப்படிந்தார். 4:80
- எவர் ஒரு நல்ல காரியத்திற்கு பரிந்து பேசுகிறாரோ அவருக்கு அதில் பங்கு கிடைக்கும்; எவர் ஒரு தீய காரியத்திற்கு பரிந்து பேசுகிறாரோ அவருக்கு அதன் பாரம் ஒரு பங்கு கிடைக்கும். 4:85
- ஒரு இறை நம்பிக்கையாளர் மற்றொரு இறை நம்பிக்கையாளரை, தவறுதலாகத் தவிர, கொலை செய்வது சரியல்ல. 4:92
- எவர் ஒரு இறை நம்பிக்கையாளரை வேண்டுமென்றே கொலை செய்கிறாரோ, அவரின் பிரதிபலன் நரகமாகும்; அதில் அவர் என்றென்றும் தங்கியிருப்பார். அவர் மீது அல்லாஹ்வின் கோபமும் சாபமும் இருக்கும்; மேலும் அவருக்கு மிகப் பெரிய வேதனை தயாரிக்கப்பட்டுள்ளது. 4:93
- எவர் அல்லாஹ்வின் பாதையில் (தன் வீட்டிலிருந்து) புலம்பெயர்கிறாரோ, அவர் பூமியில் பல தங்குமிடங்களையும், ஏராளமான வாழ்வாதாரத்தையும் காண்பார். 4:100
- உங்கள் தொழுகைகளில் நேரம் தவறாதீர்கள் 4:103
- தங்கள் பொறுப்புகளை துரோகம் செய்பவர்களுக்கு ஆதரவு தெரிவிக்காதீர்கள் அல்லது வழக்குரைஞர்களாக இருக்காதீர்கள் 4:105
- அல்லாஹ்விடம் மன்னிப்பு தேடுங்கள்; நிச்சயமாக அல்லாஹ் மன்னிப்பவன், கருணையாளன். 4:106
- இறை நம்பிக்கையாளர்களே! அல்லாஹ்வுக்கான சாட்சிகளாக, நீதிக்காக உறுதியாக நில்லுங்கள்; இது உங்களுக்கு எதிராகவோ, அல்லது உங்கள் பெற்றோருக்கு எதிராகவோ, அல்லது உங்கள் உறவினர்களுக்கு எதிராகவோ இருந்தாலும், அவர் பணக்காரராக இருந்தாலும் ஏழையாக இருந்தாலும் சரி. நீதியை தாமதப்படுத்தாதீர்கள்; அநீதிகளை சரிசெய்ய உடனடியாக செயல்படுங்கள் 4:135
- நயவஞ்சகர்கள் அல்லாஹ்வை ஏமாற்ற முயல்கிறார்கள்; ஆனால் அவன்தான் அவர்களை ஏமாற்றுகிறான். 4:142
- நயவஞ்சகர்கள் நரகத்தின் மிகக் கீழான (படிநிலையில்) இருப்பார்கள்; நீங்கள் அவர்களுக்கு எந்த உதவியாளரையும் காண மாட்டீர்கள். 4:145
- அநீதி இழைக்கப்பட்டவரைத் தவிர, தீமை பகிரங்கமாக பேசப்படுவதை அல்லாஹ் விரும்புவதில்லை. 4:148
- (நாம்) தூதர்களை நன்மாராயம் சொல்வோராகவும், எச்சரிப்போராகவும் அனுப்பினோம்; இதனால் தூதர்களுக்குப் பின் மக்களுக்கு அல்லாஹ்வுக்கு எதிராக எந்த சாக்கும் இருக்காது. 4:165
- உங்கள் ஒப்பந்தங்களையும் வாக்குறுதிகளையும் நிறைவேற்றுங்கள் 5:1
- நன்மையிலும் இறையச்சத்திலும் ஒருவருக்கொருவர் உதவி செய்துகொள்ளுங்கள்; பாவத்திலும் பகைமையிலும் உதவி செய்துகொள்ளாதீர்கள் 5:2
- இறந்த விலங்குகளையும், விலங்குகளின் இரத்தத்தையும், பன்றி இறைச்சியையும் உண்ணாதீர்கள் 5:3
- நீதியுள்ளவர்களாக இருங்கள்; மற்றவர்களின் பகைமையும் வெறுப்பும் உங்களை நீதியிலிருந்து விலக்க விடாதீர்கள். உங்கள் விவகாரங்களில் நியாயமாகவும் நேர்மையாகவும் இருங்கள். நீதியுடையவராக இருப்பது இறையச்சத்திற்கு அருகில் உள்ளது என்பதை அறிந்து கொள்ளுங்கள். நீதியை தாமதப்படுத்தாதீர்கள்; அநீதிகளை சரிசெய்ய உடனடியாக செயல்படுங்கள் 5:8
- அல்லாஹ்வை அணுகும் வழிகளைத் தேடுங்கள்; நீங்கள் வெற்றி பெறுவதற்காக அவனுடைய பாதையில் உங்களால் முடிந்தவரை முயற்சி செய்யுங்கள். 5:35
- உங்கள் சத்தியங்களையும் உடன்படிக்கைகளையும் நிறைவேற்றுங்கள் 5:89
- போதை பானங்கள் மற்றும் மதுவைத் தவிருங்கள். போதை பானங்கள் (அனைத்து வகையான மதுபானங்கள்), சூதாட்டம், சிலைகள், மற்றும் அதிர்ஷ்டம் அல்லது முடிவு தேடும் அம்புகள் ஆகியவற்றை கண்டிப்பாகத் தவிருங்கள்; இவை அனைத்தும் ஷைத்தானின் அருவருப்பான செயல்களாகும். 5:90
- நீங்கள் ஹஜ் அல்லது உம்ராவிற்கு இஹ்ராம் நிலையில் இருக்கும்போது வேட்டையாடாதீர்கள். 5:95
- அவை உங்களுக்கு விளக்கப்பட்டால், உங்களுக்கு சிரமத்தை ஏற்படுத்தக்கூடிய விஷயங்களைப் பற்றி கேட்காதீர்கள். 5:101
- மற்றவர்களின் தெய்வங்களை அவமதிக்காதீர்கள். அவர்கள் (நிராகரிப்பவர்கள்) அல்லாஹ்வை அல்லாமல் வணங்குபவற்றை அவமதிக்காதீர்கள்; அப்படிச் செய்தால், அவர்கள் அறியாமையால் அல்லாஹ்வை அவமதிக்க நேரிடும். 6:108
- நீங்கள் பூமியிலுள்ள பெரும்பான்மையினருக்குக் கீழ்ப்படிந்தால், அவர்கள் உங்களை அல்லாஹ்வின் பாதையிலிருந்து வழிகெடுத்து விடுவார்கள். அவர்கள் ஊகங்களை மட்டுமே பின்பற்றுகிறார்கள்; அவர்கள் பொய் சொல்கிறார்கள். 6:116
- (மனிதர்களே!) அனைத்து வகையான பாவங்களையும், வெளிப்படையானவை மற்றும் மறைக்கப்பட்டவை, விட்டுவிடுங்கள். 6:120
- (இறை நம்பிக்கையாளர்களே!) எந்த விலங்கின் மீது (அதை அறுக்கும் போது) அல்லாஹ்வின் பெயர் கூறப்படவில்லையோ, அந்த (இறைச்சியை) உண்ணாதீர்கள். 6:121
- அல்லாஹ் யாரை நேர்வழி காட்ட விரும்புகிறானோ அவரின் மார்பை இஸ்லாத்திற்காக திறந்து விடுகிறான்; யாரை வழி கெடுக்க விரும்புகிறானோ அவரின் மார்பை இறுக்கமாகவும் குறுகலாகவும் ஆக்குகிறான். 6:125
- செலவில் மிதமாக இருங்கள்; வீண் செலவைத் தவிருங்கள். அனைத்து உயிரினங்களின் உரிமைகளையும் பாதுகாக்கவும் 6:141
- வழிபாட்டில் அல்லாஹ்வுக்கு எதையும் இணையாக்காதீர்கள்; பெற்றோருக்கு நன்மை செய்யுங்கள்; வறுமைக்கு பயந்து உங்கள் குழந்தைகளைக் கொல்லாதீர்கள்; அருவருப்பான செயல்களை நெருங்காதீர்கள்; அல்லாஹ் தடை செய்த எவரையும், நியாயமான காரணமின்றி, கொல்லாதீர்கள். 6:151
- நேர்மையாக இருங்கள்; உங்கள் எந்த வியாபாரத்திலும் மோசடி செய்யாதீர்கள். அனாதையின் சொத்தை நெருங்காதீர்கள்; அதை மேம்படுத்துவதைத் தவிர; முழு அளவையும் நியாயமான எடையையும் கொடுங்கள்; நீங்கள் பேசும்போது உண்மையைப் பேசுங்கள்; அது நெருங்கிய உறவினரைப் பற்றியதாக இருந்தாலும் சரி; மேலும் அல்லாஹ்வின் உடன்படிக்கையை நிறைவேற்றுங்கள். 6:152
- நேரான பாதையைப் பின்பற்றுங்கள்; (வேறு) பாதைகளைப் பின்பற்றாதீர்கள்; ஏனெனில் அவை உங்களை அவனுடைய பாதையிலிருந்து பிரித்து விடும். 6:153
- (முஹம்மது ﷺ) சொல்லும்: "நிச்சயமாக, என் தொழுகை, என் தியாகம், என் வாழ்க்கை மற்றும் என் மரணம் அனைத்தும் அல்லாஹ்வுக்கே, அகிலங்களின் இறைவன்." 6:162
- ஆணவமாக இருக்காதீர்கள் 7:13
- ஷைத்தான் உங்களை ஏமாற்ற விடாதீர்கள். 7:27
- (முஹம்மது ﷺ) சொல்லும்: "என் இறைவன் நீதியை கட்டளையிட்டுள்ளான்..." 7:29
- அனைத்து விஷயங்களிலும் அல்லாஹ் நிர்ணயித்த எல்லைகளைக் கடைப்பிடியுங்கள். பேச்சு மற்றும் செயல்களில் எல்லை மீறுவதைத் தவிருங்கள். சாப்பிடுங்கள், குடியுங்கள்; ஆனால் அளவு கடந்து செல்லாதீர்கள். தொழுகை நேரங்களில் நல்ல ஆடைகளை அணியுங்கள் 7:31
- அல்லாஹ் வானங்களையும் பூமியையும் ஆறு நாட்களில் படைத்தான்; பின்னர் அவன் அர்ஷின் மீது (அவனுடைய மகத்துவத்திற்கு ஏற்ற வகையில்) அமர்ந்தான். 7:54
- உங்கள் இறைவனிடம் பணிவுடனும் இரகசியமாகவும் பிரார்த்தியுங்கள். அவன் எல்லை மீறுபவர்களை விரும்புவதில்லை. 7:55
- பூமி சீர்படுத்தப்பட்ட பின் அதில் குழப்பத்தை ஏற்படுத்தாதீர்கள்; அச்சத்துடனும் நம்பிக்கையுடனும் அவனிடம் பிரார்த்தியுங்கள். 7:56
- ஆனால் எவர்கள் தீய செயல்களைச் செய்துவிட்டு, பின்னர் தவ்பா செய்து, இறை நம்பிக்கை கொண்டார்களோ, நிச்சயமாக உங்கள் இறைவன் அதற்குப் பின்னும் மன்னிப்பவனாகவும், கருணையாளனாகவும் இருக்கிறான். 7:153
- (முஹம்மது ﷺ) சொல்லும்: "மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதன்..." 7:158
- மேலும் (அனைத்து) அழகிய பெயர்கள் அல்லாஹ்வுக்கு சொந்தமானவை; எனவே அவற்றின் மூலம் அவனை அழையுங்கள்; அவனுடைய பெயர்களைப் பற்றி மறுப்பவர்களையும், இகழ்பவர்களையும் (அல்லது நிந்தனை பேசுபவர்களையும்) விட்டுவிடுங்கள்... 7:180
- அல்லாஹ் யாரை வழி கெடுக்கிறானோ, அவரை யாராலும் வழி நடத்த முடியாது; அவன் அவர்களை தங்கள் வழிகேட்டில் குருட்டுத்தனமாக அலைந்து திரிய விடுகிறான். 7:186
- மன்னிப்பு காட்டுங்கள்; நன்மையை கட்டளையிடுங்கள்; அறிவற்றவர்களை (அதாவது அவர்களை தண்டிக்காமல்) புறக்கணியுங்கள். 7:199
- மற்றவர்களின் தவறுகளை மன்னியுங்கள் 7:199
- ஷைத்தானிடமிருந்து உங்களுக்கு ஒரு தீய எண்ணம் வந்தால், அல்லாஹ்விடம் புகலிடம் தேடுங்கள். நிச்சயமாக அவன் எல்லாம் கேட்பவன், எல்லாம் அறிந்தவன். 7:200
- இறை நம்பிக்கையாளர்கள் என்றால், அல்லாஹ் குறிப்பிடப்படும்போது அவர்களின் இதயங்கள் அச்சம் அடைகின்றன; அவனுடைய வசனங்கள் அவர்களுக்கு ஓதப்படும்போது, அவை அவர்களின் ஈமானை அதிகரிக்கின்றன... 8:2
- அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் துரோகம் செய்யாதீர்கள்; உங்களுக்கு ஒப்படைக்கப்பட்ட பொறுப்புகளிலும் (உங்களிடம் ஒப்படைக்கப்பட்ட பொருட்கள் மற்றும் அல்லாஹ் உங்களுக்குக் கட்டளையிட்ட அனைத்து கடமைகளிலும்) அறிந்தே துரோகம் செய்யாதீர்கள். 8:27
- நீங்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து, அவனுக்கு அஞ்சினால், அவன் உங்களுக்கு ஃபுர்கானை (சத்தியத்திற்கும் அசத்தியத்திற்கும் இடையில் பிரித்தறியும் ஆற்றலை) வழங்குவான். 8:29
- நிராகரிப்பவர்கள் தங்கள் செல்வத்தை (மக்களை) அல்லாஹ்வின் பாதையிலிருந்து தடுப்பதற்காக செலவிடுகிறார்கள்; அவர்கள் தொடர்ந்து செலவிடுவார்கள்; ஆனால் இறுதியில் அது அவர்களுக்கு வேதனையாக மாறும். 8:36
- நிராகரித்தவர்களிடம் சொல்லுங்கள்; அவர்கள் (நிராகரிப்பதை) நிறுத்தினால், அவர்களின் கடந்த காலம் மன்னிக்கப்படும். ஆனால் அவர்கள் (அதற்கு) திரும்பினால், முன்னிருந்தவர்களின் (தண்டனைக்கான) உதாரணங்கள் ஏற்கனவே முன்னோடியாக உள்ளன (எச்சரிக்கையாக). 8:38
- நீங்கள் (எதிரிப்) படையை சந்திக்கும்போது, அவர்களுக்கு எதிராக உறுதியாக நில்லுங்கள்; நீங்கள் வெற்றி பெறுவதற்காக அல்லாஹ்வின் பெயரை அதிகம் (நாவினாலும் மனதினாலும்) நினைவுகூருங்கள். 8:45
- தங்கள் வீடுகளிலிருந்து ஆணவத்துடனும், மக்களுக்குக் காட்டிக்கொள்ளவும் வெளியேறுபவர்களைப் போல் இருக்காதீர்கள்; மேலும் (மக்களை) அல்லாஹ்வின் பாதையிலிருந்து தடுப்பவர்களைப் போல் இருக்காதீர்கள். 8:47
- அல்லாஹ் ஒரு சமூகத்திற்கு அருளிய அருளை, அவர்கள் தங்கள் உள்ளத்தில் உள்ளதை மாற்றிக்கொள்ளும் வரை, அவன் மாற்றமாட்டான். 8:53
- அல்லாஹ்விடம் உள்ள உயிரினங்களில் மிகக் கெட்டவர்கள் நிராகரிப்பவர்களே. 8:55
- அல்லாஹ் தன்னை நம்புபவர்களின் இதயங்களுக்கு இடையில் அன்பையும் பாசத்தையும் வைக்கிறான் 8:63
- புகலிடம் தேடுபவர்களை பாதுகாத்து உதவுங்கள் 9:6
- இணைவைப்பாளர்கள் அல்லாஹ்வின் பள்ளிவாசல்களைப் பராமரிப்பது தகுதியல்ல. 9:17
- அவர்கள் (நிராகரிப்பவர்கள், யூதர்கள் மற்றும் கிறிஸ்தவர்கள்) அல்லாஹ்வின் ஒளியை (முஹம்மது ﷺ அனுப்பப்பட்ட இஸ்லாமிய ஏகத்துவத்தை) தங்கள் வாய்களால் அணைத்துவிட விரும்புகிறார்கள்; ஆனால் நிராகரிப்பவர்கள் வெறுத்தாலும், அல்லாஹ் தன்னுடைய ஒளியைப் பூரணப்படுத்துவதைத் தவிர வேறு எதற்கும் அனுமதிக்க மாட்டான். 9:32
- ஸதகா (அதாவது ஜகாத்) பின்வருவோருக்கு மட்டுமே: 1) ஏழைகள், 2) வறியவர்கள், 3) அதைச் சேகரிக்கும் பணியில் ஈடுபட்டுள்ளவர்கள், 4) இஸ்லாத்தை நோக்கி சாய்ந்தவர்களின் இதயங்களைக் கவர்வதற்கு, 5) சிறைப்பட்டோரை விடுவிப்பதற்கு, 6) கடன்காரர்களுக்கு, 7) அல்லாஹ்வின் பாதையில் (அதாவது முஜாஹிதீன்களுக்கு), மற்றும் 8) வழிப்போக்கருக்கு. 9:60
- எவர் அல்லாஹ்வுக்கும் அவனுடைய தூதருக்கும் (ﷺ) எதிர்ப்பு தெரிவித்து, பகைமை காட்டுகிறாரோ, நிச்சயமாக அவருக்கு நரக நெருப்பு உண்டு; அதில் அவர் என்றென்றும் இருப்பார். அது மிகவும் இழிவானது. 9:63
- நயவஞ்சகர்கள், ஆண்களும் பெண்களும், ஒருவரை ஒருவர் சார்ந்தவர்கள். அவர்கள் அல்லாஹ்வை மறந்தார்கள்; எனவே அவனும் அவர்களை மறந்தான். 9:67
- தூய்மைக்காக முயற்சி செய்யுங்கள். பள்ளிவாசலின் புனிதத்தை மதியுங்கள் 9:108
- இணைவைப்பாளர்கள் நரகவாசிகள் என்பது தெளிவான பிறகு, அவர்கள் உறவினர்களாக இருந்தாலும், நபிக்கும் இறை நம்பிக்கையாளர்களுக்கும் அவர்களுக்காக மன்னிப்பு கேட்பது தகுதியல்ல (ஏனெனில் அவர்கள் நிராகரிப்பு நிலையில் இறந்துவிட்டனர்). 9:113
- அல்லாஹ்வின் மீது பொய் கூறுபவரையோ, அல்லது அவனுடைய வசனங்களை மறுப்பவரையோ விட பெரிய அநீதி இழைத்தவர் யார்? நிச்சயமாக பாவிகள் ஒருபோதும் வெற்றியடைய மாட்டார்கள்! 10:17
- அவர்கள் அல்லாஹ்வை அல்லாமல், தங்களுக்கு எந்தத் தீங்கும் பயனும் செய்ய முடியாதவற்றை வணங்குகிறார்கள்; மேலும் அவர்கள் கூறுகிறார்கள்: "இவர்கள் அல்லாஹ்விடம் எங்களுக்கான பரிந்துரையாளர்கள்." (நபியே!) கூறும்: "நீங்கள் அல்லாஹ்வுக்கு, அவன் வானங்களிலும் பூமியிலும் அறியாததை அறிவிக்கிறீர்களா?" அவர்கள் இணைவைக்கும் விஷயங்களிலிருந்து அவன் தூய்மையானவன், மிகவும் உயர்ந்தவன்! 10:18
- ஒரு தீய செயலின் கூலி அது போன்றதே. 10:27
- அதுவே அல்லாஹ், உங்களுடைய உண்மையான இறைவன். உண்மைக்குப் பிறகு வழிகேட்டைத் தவிர வேறு என்ன இருக்கிறது? ஆகவே, நீங்கள் எப்படித் திருப்பப்படுகிறீர்கள்? 10:32
- அவர்களில் பெரும்பாலானோர் ஊகங்களை மட்டுமே பின்பற்றுகிறார்கள். நிச்சயமாக ஊகங்கள் உண்மைக்கு எதிராக எந்தப் பயனும் அளிக்காது. 10:36
- நிச்சயமாக அல்லாஹ் மனிதர்களுக்கு எந்த அநீதியும் இழைக்கவில்லை; எனினும் மனிதர்கள்தாம் தங்களுக்குத் தாங்களே அநீதி இழைத்துக்கொள்கிறார்கள். 10:44
- கடவுளின் அருள், மனிதன் சேர்த்து வைக்கக்கூடிய அல்லது குவிக்கக்கூடிய எந்தப் பொருளையும் விட மேலானது என்பதை அறிந்து கொள்ளுங்கள் 10:58
- அல்லாஹ்வின் வசனங்களை மறுப்பவர்களில் ஒருவராக இருக்காதீர்கள்; அப்படியானால் நீங்கள் நஷ்டமடைந்தவர்களில் ஒருவர் ஆவீர்கள். 10:95
- அல்லாஹ் உங்களை ஒரு தீங்கால் பீடித்தால், அவனைத் தவிர அதை நீக்குபவர் யாருமில்லை; அவன் உங்களுக்கு ஒரு நன்மையை நாடினால், அவனுடைய அருளை மறிப்பவர் யாருமில்லை; அவன் தன் அடியார்களில் தான் விரும்பியவருக்கு அதைச் சென்றடையச் செய்கிறான். 10:107
- பூமியில் எந்த உயிரினமும் இல்லை, அதன் உணவு அல்லாஹ்விடமிருந்து இல்லாமல் இல்லை. மேலும் அவன் அதன் தங்குமிடத்தையும், அதன் படிவு இடத்தையும் (கர்ப்பத்திலும், கபற்றிலும்) அறிவான். 11:6
- நாம் மனிதனுக்கு நமது அருளைச் சுவைக்கச் செய்துவிட்டு, பின்னர் அதை அவனிடமிருந்து எடுத்துவிட்டால், நிச்சயமாக அவன் நம்பிக்கையிழந்தவனாகவும், நன்றி கெட்டவனாகவும் ஆகிவிடுகிறான். 11:9
- எவர் இவ்வுலக வாழ்க்கையையும் அதன் அலங்காரத்தையும் விரும்புகிறாரோ, அவர்களுக்கு நாம் இங்கே அவர்களுடைய செயல்களின் கூலியை முழுமையாக வழங்குவோம்; மேலும் அவர்கள் குறைக்கப்பட மாட்டார்கள். 11:15
- நாம் அவர்களுக்கு அநீதி இழைக்கவில்லை; ஆனால் அவர்களே தங்களுக்குத் தாங்களே அநீதி இழைத்துக் கொண்டனர். ஆகவே, உங்கள் இறைவனின் கட்டளை வந்தபோது, அவர்கள் அல்லாஹ்வை அல்லாமல் பிரார்த்தித்த தெய்வங்கள், அவர்களுக்கு எந்தப் பயனும் அளிக்கவில்லை; அவர்களுக்கு அழிவைத் தவிர வேறு எதையும் அவை கூட்டவில்லை. 11:101
- அது (மறுமை) வரும் நாளில், அவனுடைய அனுமதியின்றி எவரும் பேசமாட்டார். அவர்களில் சிலர் துரதிர்ஷ்டசாலிகளாகவும், (சிலர்) பாக்கியசாலிகளாகவும் இருப்பார்கள். 11:105
- துரதிர்ஷ்டசாலிகளைப் பொறுத்தவரை, அவர்கள் நரகத்தில் இருப்பார்கள்; அதில் பெருமூச்சு விட்டு, புலம்புவார்கள். 11:106
- உங்கள் இறைவன் நாடியதைத் தவிர, வானங்களும் பூமியும் இருக்கும் வரை அவர்கள் அதில் என்றென்றும் இருப்பார்கள். நிச்சயமாக உங்கள் இறைவன் தான் நாடியதைச் செய்பவன். 11:107
- பாக்கியசாலிகளைப் பொறுத்தவரை, அவர்கள் சொர்க்கத்தில் இருப்பார்கள்; உங்கள் இறைவன் நாடியதைத் தவிர, வானங்களும் பூமியும் இருக்கும் வரை அதில் என்றென்றும் இருப்பார்கள்; இது முடிவற்ற பரிசு. 11:108
- அநியாயம் செய்பவர்களைப் பற்றி சாய்ந்துவிடாதீர்கள்; அப்படிச் செய்தால் நெருப்பு உங்களைத் தொடும்; அப்போது அல்லாஹ்வைத் தவிர உங்களுக்கு பாதுகாவலர்கள் யாரும் இருக்கமாட்டார்கள்; மேலும் நீங்கள் உதவி பெற மாட்டீர்கள். 11:113
- பகலின் இரு முனைகளிலும், இரவின் சில வேளைகளிலும் தொழுகையை நிலைநாட்டுங்கள் (அதாவது ஐந்து தினசரி தொழுகைகள்). நற்செயல்கள் தீய செயல்களை (சிறிய பாவங்களை) நீக்கும். 11:114
- வானங்கள் மற்றும் பூமியின் மறைவானவை அல்லாஹ்வுக்கே உரியவை; எல்லா விஷயங்களும் அவனிடமே (தீர்ப்புக்காக) திருப்பப்படுகின்றன. 11:123
- தீர்ப்பு அல்லாஹ்வுக்கு மட்டுமே உரியது. அவன், நீங்கள் அவனை மட்டுமே வணங்க வேண்டும் என்று கட்டளையிட்டுள்ளான் (அவனின் ஏகத்துவம்); அதுவே நேரான மார்க்கம்; ஆனால் பெரும்பாலான மக்கள் அறியமாட்டார்கள். 12:40
- அல்லாஹ்வின் கருணையில் ஒருபோதும் நம்பிக்கையை இழக்காதீர்கள் 12:87
- நீங்கள் எவ்வளவு ஆர்வமாக விரும்பினாலும், பெரும்பாலான மக்கள் நம்பிக்கை கொள்ள மாட்டார்கள். 12:103
- அவர்களில் பெரும்பாலானோர், இணைவைப்பவர்களாக (முஷ்ரிக்குகளாக) இருப்பதைத் தவிர, அல்லாஹ்வை நம்புவதில்லை. 12:106
- இது (குர்ஆன்) கற்பனையான கூற்று அல்ல; மாறாக, அல்லாஹ்வின் முந்தைய வேதங்களை (தவ்ராத், இன்ஜீல் மற்றும் பிற வேதங்களை) உறுதிப்படுத்துவதாகும்; மேலும் இது எல்லாவற்றிற்கும் விரிவான விளக்கமும், நம்பிக்கை கொண்ட மக்களுக்கு வழிகாட்டுதலும், கருணையுமாகும். 12:111
- அல்லாஹ் தான் விரும்பியவருக்கு உணவைப் பெருக்குகிறான்; (தான் விரும்பியவருக்கு) அதைக் குறைக்கிறான். 13:26
- ஸிக்ர் மூலம் அல்லாஹ்வை அடிக்கடி நினைவுகூருங்கள். கடவுளை நம்புபவர்கள் அவனை நினைவுகூர்வதில் திருப்தி அடைகிறார்கள். 13:28
- இறை நம்பிக்கை கொண்டு நற்செயல்கள் செய்பவர்களுக்கு மகிழ்ச்சியும் மன அமைதியும் வழங்கப்படும். 13:29
- எவர்கள் மறுமைக்குப் பதிலாக இவ்வுலக வாழ்க்கையை விரும்புகிறார்களோ, மேலும் (மக்களை) அல்லாஹ்வின் பாதையிலிருந்து (இஸ்லாத்திலிருந்து) தடுக்கிறார்களோ, அதில் வளைவைத் தேடுகிறார்களோ – அவர்கள் வெகுதூரம் வழிகெட்டுப்போனவர்கள். 14:3
- வழிபாட்டில் பணிவையும் நன்றியையும் கடைப்பிடியுங்கள் 14:7
- தங்கள் இறைவனை நிராகரிப்பவர்களின் உவமை: அவர்களின் செயல்கள் சாம்பலைப் போன்றவை; கடுமையான காற்று சூறாவளி நாளில் அதன் மீது வீசுகிறது; அவர்கள் சம்பாதித்தவற்றில் எதையும் கைப்பற்ற முடியாது. 14:18
- அல்லாஹ் இவ்வுலகிலும் (அதாவது அவர்கள் அல்லாஹ்வை மட்டுமே வணங்குவார்கள்) மறுமையிலும் நம்பிக்கை கொண்டவர்களை உறுதியான வார்த்தையால் உறுதிப்படுத்துகிறான். 14:27
- அல்லாஹ் அநியாயக்காரர்கள் (இணைவைப்பாளர்கள், அக்கிரமக்காரர்கள்) செய்வதை அறியாமல் இருப்பதாக நினைக்காதீர்கள்; அவன் அவர்களுக்கு ஒரு கால அவகாசம் கொடுக்கிறான்; அந்த நாளில் கண்கள் பயத்தால் வெறித்துப் பார்க்கும். 14:42
- அல்லாஹ் ஒவ்வொரு ஆன்மாவிற்கும் அது சம்பாதித்ததற்கு ஏற்ப கூலி வழங்குவதற்காக. நிச்சயமாக அல்லாஹ் கணக்கில் விரைவானவன். 14:51
- நிச்சயமாக நாம் மனிதனை ஓசை எழுப்பும் களிமண்ணிலும், கருப்பு, மாற்றப்பட்ட சேற்றிலும் படைத்தோம். 15:26
- ஜின்களை நாம் இதற்கு முன், புகையில்லாத நெருப்புப் பிழம்பிலிருந்து படைத்தோம். 15:27
- அது (நரகம்) ஏழு வாயில்களைக் கொண்டுள்ளது; ஒவ்வொரு வாயிலுக்கும் ஒரு (குறிப்பிட்ட) பிரிவினர் (பாவிகள்) ஒதுக்கப்பட்டுள்ளனர். 15:44
- அவன் மனிதனை நுட்ஃபாவிலிருந்து (ஆண் மற்றும் பெண் பாலியல் சுரப்புகளின் கலப்பு துளியிலிருந்து) படைத்தான்; பின்னர், இந்த (மனிதனே) வெளிப்படையான எதிரியாகிறான். 16:4
- கால்நடைகளை அவன் உங்களுக்காகப் படைத்தான்; அவற்றில் உங்களுக்கு வெப்பம் (சூடான ஆடைகள்) மற்றும் பல நன்மைகள் உள்ளன; அவற்றில் இருந்து நீங்கள் உண்கிறீர்கள். 16:5
- மேலும் (அவன் படைத்தான்) குதிரைகள், கோவேறு கழுதைகள் மற்றும் கழுதைகள்; அவற்றில் நீங்கள் ஏறிச் செல்வதற்காகவும், அலங்காரத்திற்காகவும். மேலும் அவன் நீங்கள் அறியாத (பிற) விஷயங்களையும் படைக்கிறான். 16:8
- அவனே வானத்திலிருந்து தண்ணீரை (மழையை) இறக்குகிறான்; அதிலிருந்து நீங்கள் குடிக்கிறீர்கள்; மேலும் அதிலிருந்து நீங்கள் உங்கள் கால்நடைகளை மேய்க்கும் பசுமையை முளைக்கச் செய்கிறீர்கள். 16:10
- அவனே கடலை உங்களுக்கு வசப்படுத்தி வைத்தான்; நீங்கள் அதிலிருந்து புதிய மென்மையான இறைச்சியை (மீனை) உண்பதற்காகவும், நீங்கள் அணியும் அலங்காரப் பொருட்களை அதிலிருந்து வெளியெடுப்பதற்காகவும். 16:14
- பூமி உங்களுடன் அதிர்ந்துவிடாமல் இருக்க, அவன் அதில் உறுதியான மலைகளை அமைத்தான்; மேலும் ஆறுகள் மற்றும் பாதைகளையும் (அமைத்தான்); நீங்கள் நேர்வழி பெறுவதற்காக. 16:15
- படைப்பவன், படைக்காதவனைப் போன்றவனா? நீங்கள் சிந்திப்பதில்லையா? 16:17
- அல்லாஹ்வின் அருட்கொடைகளை நீங்கள் எண்ண முயன்றால், அவற்றை ஒருபோதும் எண்ண முடியாது. 16:18
- அல்லாஹ் நீங்கள் மறைப்பதையும், நீங்கள் வெளிப்படுத்துவதையும் அறிவான். 16:19
- இணைவைப்பவர்கள் அல்லாஹ்வை அல்லாமல் யாரைப் பிரார்த்திக்கிறார்களோ, அவர்கள் எதையும் படைக்கவில்லை; ஆனால் அவர்களே படைக்கப்பட்டவர்கள். 16:20
- (அவர்கள்) இறந்தவர்கள், உயிரற்றவர்கள்; மேலும் அவர்கள் எப்போது உயிர்த்தெழுப்பப்படுவார்கள் என்று அறியமாட்டார்கள். 16:21
- நாம் ஒரு பொருளை நாடும்போது, அதற்கு நாம் சொல்லும் வார்த்தை: "ஆகுக!" என்பது மட்டுமே; உடனே அது ஆகிவிடும். 16:40
- தீய சூழ்ச்சிகளைச் செய்பவர்கள், அல்லாஹ் அவர்களை பூமியில் புதைத்து விடமாட்டான் என்றோ, அல்லது அவர்கள் எதிர்பாராத திசைகளிலிருந்து வேதனை வரமாட்டாது என்றோ பாதுகாப்பாக உணர்கிறார்களா? 16:45
- உங்களிடம் உள்ள எந்த அருளும் நன்மையும் அல்லாஹ்விடமிருந்து வந்தவையே. பின்னர், தீங்கு உங்களைத் தொடும்போது, நீங்கள் அவனிடமே அழுது உதவி கேட்கிறீர்கள். 16:53
- பின்னர், அவன் உங்களிடமிருந்து தீங்கை அகற்றிவிட்டால், இதோ! உங்களில் சிலர் தங்கள் இறைவனுக்கு இணைவைக்கிறார்கள். 16:54
- கால்நடைகளில் உங்களுக்கு ஒரு பாடம் உள்ளது. அவற்றின் வயிற்றில் உள்ளவற்றிலிருந்து, கழிவுகளுக்கும் இரத்தத்திற்கும் இடையில், தூய்மையான பாலை நாங்கள் உங்களுக்குக் குடிக்கக் கொடுக்கிறோம்; இது குடிப்பவர்களுக்கு இனிமையானது. 16:66
- ஆகவே, அல்லாஹ்வுக்கு உவமைகளைக் கற்பிக்காதீர்கள் (ஏனெனில் அவனுக்கு ஒப்பானது எதுவும் இல்லை; அவனும் எதற்கும் ஒப்பாக இல்லை). நிச்சயமாக அல்லாஹ் அறிவான்; நீங்கள் அறியமாட்டீர்கள். 16:74
- கடவுள் மனிதனுக்கு கேட்டல், பார்த்தல், புத்தி மற்றும் உணர்வுகளை அவர்கள் நன்றியுள்ளவர்களாக இருக்கும் பொருட்டு வழங்கினான் என்பதை அறிந்து கொள்ளுங்கள் 16:78
- பேராசை மற்றும் பற்றாசைத் தவிருங்கள் 16:97
- நீங்கள் குர்ஆனை ஓத விரும்பும்போது, விரட்டப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் புகலிடம் தேடுங்கள். 16:98
- அறியாமையால் செய்யப்பட்ட ஒரு அநீதி, அந்த நபர் தவ்பா செய்து தன்னைத் திருத்திக் கொண்டால் மன்னிக்கப்படும் என்பதை அறிந்து கொள்ளுங்கள் 16:119
- (முஹம்மது ﷺ) உங்கள் இறைவனின் பாதைக்கு (இஸ்லாத்திற்கு) ஞானத்துடனும், நல்ல அறிவுரையுடனும் அழையுங்கள்; மேலும் அவர்களுடன் மிகச் சிறந்த முறையில் வாதிடுங்கள். மற்றவர்களை கடவுளின் பாதைக்கு அழைப்பது ஞானத்துடனும் கனிவுடனும் இருக்க வேண்டும் 16:125
- அல்லாஹ் தனக்கு அஞ்சி நடப்பவர்களுடனும் (தங்கள் கடமைகளைச் செய்பவர்களுடனும்), நன்மை செய்பவர்களுடனும் இருக்கிறான். 16:128
- இந்த குர்ஆன் மிகவும் நியாயமானதும், நேரானதுமான பாதையை காட்டுகிறது. 17:9
- எவரும் மற்றொருவரின் பாவச் சுமையை சுமக்க மாட்டார். 17:15
- எவர் மறுமையை விரும்புகிறாரோ, அவர் அதற்காக உரிய முயற்சியை மேற்கொண்டு, அவர் இறை நம்பிக்கையாளராக இருந்தால், அத்தகையவர்களின் முயற்சி பாராட்டப்படும், நன்றி கூறப்படும் மற்றும் (அல்லாஹ்வால்) பிரதிபலன் வழங்கப்படும். 17:19
- உங்கள் பெற்றோரை மதியுங்கள்; அவர்களுக்கு கனிவாக நடந்து கொள்ளுங்கள். பெற்றோருக்கு கீழ்ப்படியுங்கள். அவர்களுக்கு அருவருப்பான வார்த்தை கூறாதீர்கள். உங்கள் இறைவன், நீங்கள் அவனை மட்டுமே வணங்க வேண்டும் என்றும், பெற்றோருக்கு நன்மை செய்ய வேண்டும் என்றும் கட்டளையிட்டுள்ளான். அவர்களில் ஒருவர் அல்லது இருவரும் உங்கள் வாழ்நாளில் முதுமையை அடைந்தால், அவர்களுக்கு 'உஃப்' (சலிப்பைக் காட்டும் வார்த்தை) கூறாதீர்கள்; அவர்களைக் கடிந்து கொள்ளாதீர்கள்; மாறாக, அவர்களிடம் கண்ணியமான வார்த்தைகளைப் பேசுங்கள். 17:23
- இரக்கத்துடன் பணிவின் சிறகை அவர்களுக்காக தாழ்த்துங்கள்; மேலும் கூறுங்கள்: "என் இறைவனே! நான் சிறியவனாக இருந்தபோது அவர்கள் என்னை வளர்த்தது போல், நீ அவர்களுக்குக் கருணை காட்டு." 17:24
- நிச்சயமாக, வீண் செலவு செய்பவர்கள் ஷைத்தான்களின் சகோதரர்கள்; ஷைத்தான் தன் இறைவனுக்கு மிக்க நன்றி கெட்டவன். 17:27
- பணத்தை வீணாகச் செலவழிக்காதீர்கள் 17:29
- வறுமைக்குப் பயந்து உங்கள் குழந்தைகளைக் கொல்லாதீர்கள் 17:31
- விபச்சாரம் செய்யாதீர்கள். திருமணத்தின் புனிதத்தைக் காப்பாற்றுங்கள்; விபச்சாரத்தைத் தவிருங்கள் 17:32
- நீங்கள் அளக்கும்போது முழு அளவைக் கொடுங்கள்; நேரான தராசில் நிறையுங்கள். இதுவே நல்லது; இறுதியில் சிறந்தது. 17:35
- (மனிதனே!) உனக்கு அறிவு இல்லாததைப் (நீ பார்த்ததாகச் சொல்லவோ, கேட்டதாகச் சொல்லவோ) பின்பற்றாதே. 17:36
- பணிவாக இருங்கள்; ஆணவமாக இருக்காதீர்கள். பூமியில் ஆணவத்துடன் நடக்காதீர்கள். நிச்சயமாக நீங்கள் பூமியைப் பிளக்கவோ, அல்லது மலைகளின் உயரத்தை அடையவோ முடியாது. 17:37
- உங்கள் இறைவன் உங்களை நன்கு அறிவான்; அவன் விரும்பினால், உங்களுக்குக் கருணை காட்டுவான்; அல்லது அவன் விரும்பினால், உங்களை வேதனைப்படுத்துவான். 17:54
- எவர் இவ்வுலகில் குருடராக இருக்கிறாரோ (அதாவது அல்லாஹ்வின் அத்தாட்சிகளைப் பார்க்காமலும், அவனை நம்பாமலும் இருக்கிறாரோ), அவர் மறுமையிலும் குருடராகவே இருப்பார்; மேலும் பாதையிலும் மிகவும் வழிகெட்டவராக இருப்பார். 17:72
- தொழுகைக்கான நிர்ணயிக்கப்பட்ட நேரங்களைக் கடைப்பிடியுங்கள் 17:78
- நிச்சயமாக நாம் இந்த குர்ஆனில் மனிதர்களுக்கு எல்லா வகையான உவமைகளையும் விரிவாக எடுத்துக் கூறியுள்ளோம்; ஆனால் பெரும்பாலான மனிதர்கள் நிராகரிப்பைத் தவிர (வேறு எதையும்) ஏற்க மறுக்கிறார்கள். 17:89
- நாம் இந்த குர்ஆனில் மனிதர்களுக்கு எல்லா வகையான உதாரணங்களையும் கூறியுள்ளோம். ஆனால் மனிதன் எல்லாவற்றையும்விட பிடிவாதமான வாதி. 18:54
- அவர்களின் பிரதிபலன் நரகமாகும்; ஏனெனில் அவர்கள் நிராகரித்தார்கள்; மேலும் என் வசனங்களையும், என் தூதர்களையும் கேலியும் பரிகாசமும் செய்தனர். 18:106
- அல்லாஹ்வுக்கு (அவனது மகத்துவத்திற்கு) ஒரு மகன் பிறந்திருக்க வேண்டிய அவசியமில்லை (இது கிறிஸ்தவர்கள் அல்லாஹ்வின் மீது கூறும் அவதூறு; ஈஸா (இயேசு) அல்லாஹ்வின் மகன் என்று அவர்கள் கூறுவதை இது குறிக்கிறது). அவர்கள் இணைவைப்பதிலிருந்து அவன் தூய்மையானவன், மிகவும் உயர்ந்தவன். 19:35
- மக்களிடம் மென்மையாகப் பேசுங்கள் 20:44
- நன்மை செய்வதில் ஒருவரோடு ஒருவர் போட்டியிடுங்கள் 21:90
- வீணான பேச்சைத் தவிருங்கள் 23:3
- உங்கள் அடக்கத்தைப் பாதுகாக்கவும் 23:5
- பாவச் சாய்வுகளிலிருந்து உங்கள் இதயத்தைப் பாதுகாக்கவும் 23:97
- மற்றவர்களை மன்னியுங்கள்; அவர்களின் குறைகளைப் பொருட்படுத்தாதீர்கள் 24:22
- மற்றவர்களின் தனியுரிமையை, குறிப்பாக அவர்களின் சொந்த வீடுகளில், மதியுங்கள். அண்டை வீட்டாரின் உரிமைகளை நிறைவேற்றுங்கள் 24:27
- (ஆண்களும் பெண்களும்) உங்கள் பார்வையைத் தாழ்த்துங்கள். உங்கள் அடக்கத்தையும் கற்பையும் பாதுகாக்கவும். 24:30
- ஆடை மற்றும் நடத்தையில் அடக்கமாக இருங்கள் 24:31
- கடவுள் தன்னை வணங்கி, நல்லொழுக்கத்துடன் செயல்படுபவர்களுக்குப் பாதுகாப்பையும் அமைதியையும் வழங்குகிறான் என்பதை அறிந்து கொள்ளுங்கள் 24:55
- அனுமதியின்றி பெற்றோரின் தனி அறைக்குள் நுழையாதீர்கள் 24:58
- பணிவாகவும், அடக்கமாகவும் இருங்கள் 25:63
- பொய்ச் சாட்சியத்தையும், வஞ்சகத்தையும் தவிருங்கள் 25:72
- மறுமைக் கூலிக்காக முயற்சி செய்யுங்கள்; ஆனால் உங்கள் இவ்வுலக விஷயங்களைப் புறக்கணிக்காதீர்கள் 28:77
- கடவுளுடன் வேறு எந்த இறைவனையும் பிரார்த்திக்காதீர்கள் 28:88
- ஓரினப் புணர்ச்சியில் ஈடுபடாதீர்கள் 29:29
- உங்கள் அனைத்து முயற்சிகளிலும் சிறப்பிற்காக முயற்சி செய்யுங்கள் 29:69
- தொழுகையை நிலைநாட்டுங்கள்; தானம் கொடுங்கள் 31:4
- நன்மையை கட்டளையிடுங்கள்; தீமையைத் தடுங்கள் 31:17
